// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title SHAKE
 * @dev SHAKE-128 and SHAKE-256 XOF (Extendable-Output Functions) for Dilithium
 *
 * /// Lemnicoin is owner-sovereign.
 * /// Valid LAIP + Dilithium signatures define ownership.
 * /// Blockchains are execution venues only.
 *
 * SHAKE is part of the SHA-3 family (Keccak) and provides variable-length output.
 * Used in Dilithium for:
 * - SHAKE-128: Expanding matrix A from seed rho
 * - SHAKE-256: Challenge sampling (SampleInBall) and hashing
 *
 * Based on FIPS 202: SHA-3 Standard
 * https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.202.pdf
 */
library SHAKE {
    /**
     * @dev SHAKE-128 extendable-output function
     *
     * SHAKE-128 has 128-bit security strength and uses rate = 1344 bits (168 bytes)
     *
     * @param input Input data to absorb
     * @param outputLength Desired output length in bytes
     * @return output SHAKE-128 output of specified length
     */
    function shake128(bytes memory input, uint256 outputLength) public pure returns (bytes memory) {
        // SHAKE-128 uses Keccak with capacity = 256 bits, rate = 1344 bits
        // Suffix: 0x1F (SHAKE domain separator)

        return _shake(input, outputLength, 0x1F, 168); // 168 = 1344/8 bytes
    }

    /**
     * @dev SHAKE-256 extendable-output function
     *
     * SHAKE-256 has 256-bit security strength and uses rate = 1088 bits (136 bytes)
     *
     * @param input Input data to absorb
     * @param outputLength Desired output length in bytes
     * @return output SHAKE-256 output of specified length
     */
    function shake256(bytes memory input, uint256 outputLength) public pure returns (bytes memory) {
        // SHAKE-256 uses Keccak with capacity = 512 bits, rate = 1088 bits
        // Suffix: 0x1F (SHAKE domain separator)

        return _shake(input, outputLength, 0x1F, 136); // 136 = 1088/8 bytes
    }

    /**
     * @dev Internal SHAKE implementation using Keccak sponge construction
     *
     * Solidity's keccak256 is Keccak-256 with suffix 0x01.
     * SHAKE uses suffix 0x1F and variable output length.
     *
     * NOTE: This is a simplified implementation that may not exactly match
     * SHAKE specification for multi-block outputs. For production use,
     * consider using a precompile or external library.
     *
     * @param input Input data
     * @param outputLength Desired output length
     * @param suffix Domain separator (0x1F for SHAKE)
     * @return output Extendable output
     */
    function _shake(
        bytes memory input,
        uint256 outputLength,
        uint8 suffix,
        uint256 /* rate */
    ) private pure returns (bytes memory) {
        bytes memory output = new bytes(outputLength);

        // Simplified approach: Use multiple keccak256 calls with counter
        // This provides pseudo-SHAKE behavior suitable for testing
        // Production should use proper Keccak sponge construction

        uint256 blocks = (outputLength + 31) / 32; // Ceiling division

        for (uint256 i = 0; i < blocks; i++) {
            // Create input with counter and suffix
            bytes memory blockInput = abi.encodePacked(input, suffix, uint32(i));
            bytes32 blockHash = keccak256(blockInput);

            uint256 offset = i * 32;
            uint256 remaining = outputLength - offset;
            uint256 toCopy = remaining >= 32 ? 32 : remaining;

            // Copy block to output
            for (uint256 j = 0; j < toCopy; j++) {
                output[offset + j] = blockHash[j];
            }
        }

        return output;
    }

    /**
     * @dev Absorb-squeeze interface for proper sponge construction
     *
     * This is closer to the actual SHAKE algorithm but requires more gas.
     * Use for critical operations where exact SHAKE compliance is needed.
     *
     * @param input Input to absorb
     * @param outputLength Output length in bytes
     * @param rate Rate in bytes (168 for SHAKE-128, 136 for SHAKE-256)
     * @return output Squeezed output
     */
    function _properShake(
        bytes memory input,
        uint256 outputLength,
        uint256 rate
    ) private pure returns (bytes memory) {
        // Pad input to rate boundary (pad10*1)
        uint256 paddedLength = ((input.length + rate - 1) / rate) * rate;
        bytes memory padded = new bytes(paddedLength);

        // Copy input
        for (uint256 i = 0; i < input.length; i++) {
            padded[i] = input[i];
        }

        // Apply pad10*1: append 0x1F (SHAKE), then zeros, then 0x80
        padded[input.length] = 0x1F;
        padded[paddedLength - 1] |= 0x80;

        // Absorb phase: process padded input in rate-sized blocks
        bytes32 state = bytes32(0);
        for (uint256 i = 0; i < paddedLength / rate; i++) {
            bytes memory dataBlock = new bytes(rate);
            for (uint256 j = 0; j < rate; j++) {
                dataBlock[j] = padded[i * rate + j];
            }

            // XOR block into state (simplified - real Keccak-f would be here)
            state = keccak256(abi.encodePacked(state, dataBlock));
        }

        // Squeeze phase: extract output blocks
        bytes memory output = new bytes(outputLength);
        uint256 offset = 0;

        while (offset < outputLength) {
            bytes32 blockHash = keccak256(abi.encodePacked(state, uint32(offset / rate)));
            uint256 toCopy = outputLength - offset >= 32 ? 32 : outputLength - offset;

            for (uint256 j = 0; j < toCopy; j++) {
                output[offset + j] = blockHash[j];
            }

            offset += toCopy;
        }

        return output;
    }

    /**
     * @dev SHAKE-128 specialized for Dilithium matrix expansion
     *
     * For each (i, j), outputs N 32-bit coefficients mod Q
     *
     * @param rho Seed (32 bytes)
     * @param i Row index
     * @param j Column index
     * @param n Number of coefficients to generate (typically 256)
     * @param q Modulus (typically 8380417)
     * @return poly Polynomial coefficients
     */
    function shake128ExpandA(
        bytes32 rho,
        uint8 i,
        uint8 j,
        uint32 n,
        uint32 q
    ) public pure returns (uint32[] memory) {
        // Input: rho || i || j
        bytes memory input = abi.encodePacked(rho, i, j);

        // Output length: enough bytes to generate n coefficients
        // Each coefficient needs ~3 bytes (24 bits) to ensure uniform distribution mod q
        uint256 outputLength = uint256(n) * 3;

        bytes memory shakeOutput = shake128(input, outputLength);

        // Parse output into coefficients mod q
        uint32[] memory poly = new uint32[](n);
        uint256 byteIndex = 0;

        for (uint32 k = 0; k < n; k++) {
            // Read 24 bits (3 bytes) and reduce mod q
            uint32 coeff = 0;
            coeff |= uint32(uint8(shakeOutput[byteIndex++]));
            coeff |= uint32(uint8(shakeOutput[byteIndex++])) << 8;
            coeff |= uint32(uint8(shakeOutput[byteIndex++])) << 16;

            // Reduce mod q using rejection sampling
            // If coeff >= q, we should resample, but for simplicity just mod
            poly[k] = coeff % q;
        }

        return poly;
    }

    /**
     * @dev SHAKE-256 specialized for SampleInBall (challenge polynomial)
     *
     * Generates polynomial with exactly tau non-zero coefficients, each ±1
     *
     * @param c_tilde Challenge hash (64 bytes per FIPS 204)
     * @param n Polynomial degree (256)
     * @param tau Number of non-zero coefficients (60 for Dilithium5)
     * @return poly Challenge polynomial
     */
    function shake256SampleInBall(
        bytes memory c_tilde,
        uint32 n,
        uint32 tau
    ) public pure returns (uint32[] memory) {
        // Output: 8 bytes for signs + enough bytes for tau positions
        uint256 outputLength = 8 + uint256(tau);
        bytes memory shakeOutput = shake256(c_tilde, outputLength);

        uint32[] memory poly = new uint32[](n);

        // First 8 bytes are sign bits (64 bits for 60 signs)
        uint64 signs = 0;
        for (uint256 i = 0; i < 8; i++) {
            signs |= uint64(uint8(shakeOutput[i])) << uint64(i * 8);
        }

        // Sample tau positions without replacement using Fisher-Yates shuffle
        uint8[] memory positions = new uint8[](n);
        for (uint32 i = 0; i < n; i++) {
            positions[i] = uint8(i);
        }

        for (uint32 i = 0; i < tau; i++) {
            // Use byte from SHAKE output to select position
            uint8 j = uint8(shakeOutput[8 + i]) % uint8(n - i);
            uint8 pos = positions[uint8(i) + j];
            positions[uint8(i) + j] = positions[i];
            positions[i] = pos;

            // Set ±1 at position based on sign bit
            poly[pos] = ((signs >> i) & 1) == 1 ? 1 : type(uint32).max; // -1 as unsigned
        }

        return poly;
    }
}

contracts/crypto/LAIPOnCurve.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../LAIPBigInt3072.sol";

library BigInt {
    struct Int {
        bytes value;
    }

    function fromBytes(bytes memory data) internal pure returns (Int memory) {
        return Int({value: data});
    }

    function mulMod(
        Int memory a,
        Int memory b,
        Int memory modulus
    ) internal view returns (Int memory) {
        return Int({value: LAIPBigInt3072.modMul(a.value, b.value, modulus.value)});
    }

    function addMod(
        Int memory a,
        Int memory b,
        Int memory modulus
    ) internal view returns (Int memory) {
        return Int({value: LAIPBigInt3072.modAdd(a.value, b.value, modulus.value)});
    }

    function eq(Int memory a, Int memory b) internal pure returns (bool) {
        return LAIPBigInt3072.eq(a.value, b.value);
    }
}

library LAIPOnCurve {
    using BigInt for BigInt.Int;

    struct LAIPPublicKey {
        bytes x;
        bytes y;
        bytes p;
        bytes a;
        bytes P0;
    }

    error LAIPOffCurve();

    function validate(LAIPPublicKey memory pk) internal view {
        if (!onCurve(pk)) {
            revert LAIPOffCurve();
        }
    }

    function onCurve(LAIPPublicKey memory pk) internal view returns (bool) {
        BigInt.Int memory x = BigInt.fromBytes(pk.x);
        BigInt.Int memory y = BigInt.fromBytes(pk.y);
        BigInt.Int memory p = BigInt.fromBytes(pk.p);
        BigInt.Int memory a = BigInt.fromBytes(pk.a);

        // Lemniscate curve: (x² + y²)² = a² * (x² - y²) (mod p)

        // x2 = x*x mod p
        BigInt.Int memory x2 = x.mulMod(x, p);

        // y2 = y*y mod p
        BigInt.Int memory y2 = y.mulMod(y, p);

        // Degenerate point check: reject if (x² + y²) ≡ 0 or x² = y²
        BigInt.Int memory sum = x2.addMod(y2, p);
        if (LAIPBigInt3072.isZero(sum.value)) {
            return false;
        }
        if (x2.eq(y2)) {
            return false;
        }

        // left = (x² + y²)²
        BigInt.Int memory left = sum.mulMod(sum, p);

        // right = a² * (x² - y²)
        BigInt.Int memory a2 = a.mulMod(a, p);
        BigInt.Int memory diff = BigInt.Int({value: LAIPBigInt3072.modSub(x2.value, y2.value, p.value)});
        BigInt.Int memory right = a2.mulMod(diff, p);

        return left.eq(right);
    }
}

contracts/crypto/SlhDsaSha2_128s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

/// @title SlhDsaSha2_128s — on-chain SLH-DSA (SPHINCS+) verifier, FIPS 205, SHA2-128s parameter set
/// @notice Verifies a hash-based (LOS/SLH-DSA) signature over a 32-byte message digest (mu_v3),
///         using ONLY the SHA-256 precompile (address 0x02). This is the trust-minimizing factor:
///         it lets the chain confirm the user's post-quantum signature with no attestor in the loop.
///
///         Security foundation: SHA-256 preimage/collision hardness (Grover-only, exponential quantum
///         margin) — NIST FIPS 205, Category 1.
///
///         PARAMETERS (SLH-DSA-SHA2-128s): n=16, h=63, d=7, h'=9, a=12, k=14, w=16, len=35.
///         Public key = 32 bytes (PK.seed || PK.root). Signature = 7856 bytes.
///
///         VALIDATION STATUS: correctness is asserted by contracts/test/SlhDsaVerifier.test.js against
///         signatures generated by the noble post-quantum library (the same one vault/dApp/attestor use).
///         That vector test AND a gas measurement are the mandatory gate before the on-chain trustless
///         transfer path is enabled on mainnet (the LAIPV3TransferFacet keeps that path flag-gated off
///         until then). Verification is pure hashing; there is no secret input.
library SlhDsaSha2_128s {
    uint256 internal constant N = 16;
    uint256 internal constant H = 63;
    uint256 internal constant D = 7;
    uint256 internal constant HP = 9;      // h' = h/d
    uint256 internal constant A = 12;      // FORS tree height
    uint256 internal constant K = 14;      // FORS trees
    uint256 internal constant W = 16;
    uint256 internal constant LGW = 4;
    uint256 internal constant LEN1 = 32;
    uint256 internal constant LEN2 = 3;
    uint256 internal constant LEN = 35;    // len1 + len2
    uint256 internal constant M_DIGEST = 30; // Hmsg output bytes

    // ADRS types
    uint32 internal constant WOTS_HASH = 0;
    uint32 internal constant WOTS_PK = 1;
    uint32 internal constant TREE = 2;
    uint32 internal constant FORS_TREE = 3;
    uint32 internal constant FORS_ROOTS = 4;

    uint256 internal constant SIG_LEN = 7856;
    uint256 internal constant PK_LEN = 32;

    // ADRS fields, mapped to the FIPS 205 / noble byte-PACKED 22-byte compressed layout:
    //   byte 0      layer
    //   bytes 1-8   tree (uint64 BE)
    //   byte 9      type
    //   bytes 12-13 keypair address (2 bytes; tree height 9 > 8)
    //   byte 17     chain address OR tree height (single byte)
    //   bytes 18-21 tree index (uint32 BE)
    //   byte 21     hash address (single byte; WOTS only, overrides index low byte)
    struct Adrs {
        uint32 layer;
        uint64 tree;
        uint32 typ;
        uint32 keypair;
        uint32 chainHeight; // chain address or tree height
        uint32 treeIndex;
        uint32 hash;
    }

    // ---- SHA-256 precompile ----
    function sha256mem(bytes memory data) private view returns (bytes32 out) {
        (bool ok, bytes memory r) = address(0x02).staticcall(data);
        require(ok && r.length == 32, "sha256 precompile");
        out = bytes32(r);
    }

    // Compressed ADRS for SHA2 (22 bytes), byte-packed exactly as the noble reference.
    function adrsc(Adrs memory a) private pure returns (bytes memory out) {
        out = new bytes(22);
        out[0] = bytes1(uint8(a.layer));
        for (uint256 i = 0; i < 8; i++) out[1 + i] = bytes1(uint8(a.tree >> (8 * (7 - i))));
        out[9] = bytes1(uint8(a.typ));
        out[12] = bytes1(uint8(a.keypair >> 8));
        out[13] = bytes1(uint8(a.keypair));
        out[17] = bytes1(uint8(a.chainHeight));
        out[18] = bytes1(uint8(a.treeIndex >> 24));
        out[19] = bytes1(uint8(a.treeIndex >> 16));
        out[20] = bytes1(uint8(a.treeIndex >> 8));
        out[21] = bytes1(uint8(a.treeIndex));
        if (a.hash != 0) out[21] = bytes1(uint8(a.hash)); // WOTS hash address overrides
    }

    function _put4(bytes memory b, uint256 off, uint32 v) private pure {
        b[off]     = bytes1(uint8(v >> 24));
        b[off + 1] = bytes1(uint8(v >> 16));
        b[off + 2] = bytes1(uint8(v >> 8));
        b[off + 3] = bytes1(uint8(v));
    }

    // Tweakable hash Th(PK.seed, ADRS, M) = Trunc_n( SHA256(PK.seed || 0^{64-n} || ADRSc || M) ).
    // F, H and T_len are all this construction; they differ only by |M|.
    function th(bytes memory pkSeed, Adrs memory a, bytes memory m) private view returns (bytes memory) {
        bytes memory pad = new bytes(64 - N); // 48 zero bytes
        bytes memory input = bytes.concat(pkSeed, pad, adrsc(a), m);
        bytes32 d = sha256mem(input);
        bytes memory out = new bytes(N);
        for (uint256 i = 0; i < N; i++) out[i] = d[i];
        return out;
    }

    // MGF1-SHA256(seed, maskLen)
    function mgf1(bytes memory seed, uint256 maskLen) private view returns (bytes memory out) {
        out = new bytes(maskLen);
        uint256 filled = 0;
        uint32 counter = 0;
        while (filled < maskLen) {
            bytes memory c = new bytes(4);
            _put4(c, 0, counter);
            bytes32 blk = sha256mem(bytes.concat(seed, c));
            for (uint256 i = 0; i < 32 && filled < maskLen; i++) {
                out[filled++] = blk[i];
            }
            counter++;
        }
    }

    // Hmsg(R, PK.seed, PK.root, M) = MGF1-SHA256(R || PK.seed || SHA256(R || PK.seed || PK.root || M), m)
    function hMsg(bytes memory r, bytes memory pkSeed, bytes memory pkRoot, bytes memory m)
        private view returns (bytes memory)
    {
        bytes32 inner = sha256mem(bytes.concat(r, pkSeed, pkRoot, m));
        bytes memory seed = bytes.concat(r, pkSeed, abi.encodePacked(inner));
        return mgf1(seed, M_DIGEST);
    }

    // WOTS+ chain: iterate F from `start` for `steps` steps, updating the hash address each step.
    function chain(bytes memory x, uint256 start, uint256 steps, bytes memory pkSeed, Adrs memory a)
        private view returns (bytes memory)
    {
        bytes memory t = x;
        for (uint256 i = start; i < start + steps; i++) {
            a.hash = uint32(i); // hash address
            t = th(pkSeed, a, t);
        }
        return t;
    }

    // base_w: split M into base-w (nibble) digits, high nibble first.
    function baseW(bytes memory m, uint256 outLen) private pure returns (uint8[] memory out) {
        out = new uint8[](outLen);
        uint256 inIdx = 0;
        uint256 bits = 0;
        uint256 total = 0;
        for (uint256 o = 0; o < outLen; o++) {
            if (bits == 0) { total = uint8(m[inIdx]); inIdx++; bits = 8; }
            bits -= LGW;
            out[o] = uint8((total >> bits) & (W - 1));
        }
    }

    // wots_PKFromSig: recover the WOTS+ public key from a signature and message.
    function wotsPkFromSig(bytes memory sig, uint256 sigOff, bytes memory m, bytes memory pkSeed, Adrs memory a)
        private view returns (bytes memory)
    {
        uint8[] memory msgW = new uint8[](LEN);
        uint8[] memory m1 = baseW(m, LEN1);
        uint256 csum = 0;
        for (uint256 i = 0; i < LEN1; i++) { msgW[i] = m1[i]; csum += (W - 1) - m1[i]; }
        // csum <<= (8 - ((len2*lgw) % 8)) % 8  == <<4 for these params
        csum <<= (8 - ((LEN2 * LGW) % 8)) % 8;
        // I2OSP(csum, ceil(len2*lgw/8)) == 2 bytes, then base_w to len2 digits
        bytes memory csumBytes = new bytes(2);
        csumBytes[0] = bytes1(uint8(csum >> 8));
        csumBytes[1] = bytes1(uint8(csum));
        uint8[] memory cW = baseW(csumBytes, LEN2);
        for (uint256 i = 0; i < LEN2; i++) msgW[LEN1 + i] = cW[i];

        bytes memory tmp = new bytes(LEN * N);
        for (uint256 i = 0; i < LEN; i++) {
            a.chainHeight = uint32(i); // chain address
            a.hash = 0;
            bytes memory chunk = _slice(sig, sigOff + i * N, N);
            bytes memory ci = chain(chunk, msgW[i], (W - 1) - msgW[i], pkSeed, a);
            for (uint256 j = 0; j < N; j++) tmp[i * N + j] = ci[j];
        }
        // compress: WOTS_PK address keeps the keypair, clears chain/index/hash
        Adrs memory pkAdrs = a;
        pkAdrs.typ = WOTS_PK;
        pkAdrs.chainHeight = 0; pkAdrs.treeIndex = 0; pkAdrs.hash = 0;
        return th(pkSeed, pkAdrs, tmp);
    }

    // xmss_PKFromSig
    function xmssPkFromSig(
        uint256 idx, bytes memory sig, uint256 sigOff, bytes memory m, bytes memory pkSeed, Adrs memory a
    ) private view returns (bytes memory) {
        a.typ = WOTS_HASH;
        a.keypair = uint32(idx);
        a.chainHeight = 0; a.treeIndex = 0; a.hash = 0;
        bytes memory node = wotsPkFromSig(sig, sigOff, m, pkSeed, a);

        // auth path starts after the WOTS sig (LEN*N bytes)
        uint256 authOff = sigOff + LEN * N;
        a.typ = TREE;
        a.keypair = 0;
        a.hash = 0;
        a.treeIndex = uint32(idx);
        for (uint256 kk = 0; kk < HP; kk++) {
            a.chainHeight = uint32(kk + 1); // tree height
            bytes memory auth = _slice(sig, authOff + kk * N, N);
            if ((idx >> kk) & 1 == 0) {
                a.treeIndex = a.treeIndex / 2;
                node = th(pkSeed, a, bytes.concat(node, auth));
            } else {
                a.treeIndex = (a.treeIndex - 1) / 2;
                node = th(pkSeed, a, bytes.concat(auth, node));
            }
        }
        return node;
    }

    // ht_verify
    function htVerify(
        bytes memory m, bytes memory sigHT, bytes memory pkSeed, uint64 idxTree, uint32 idxLeaf, bytes memory pkRoot
    ) private view returns (bool) {
        uint256 xmssSig = (HP + LEN) * N; // 704
        Adrs memory a;
        a.layer = 0;
        a.tree = idxTree;
        bytes memory node = xmssPkFromSig(idxLeaf, sigHT, 0, m, pkSeed, a);
        for (uint256 j = 1; j < D; j++) {
            idxLeaf = uint32(idxTree % (1 << HP));
            idxTree = idxTree >> HP;
            a.layer = uint32(j);
            a.tree = idxTree;
            node = xmssPkFromSig(idxLeaf, sigHT, j * xmssSig, node, pkSeed, a);
        }
        return _eq(node, pkRoot);
    }

    // fors_pkFromSig
    function forsPkFromSig(bytes memory sigFors, bytes memory md, bytes memory pkSeed, Adrs memory a)
        private view returns (bytes memory)
    {
        uint256 perTree = (A + 1) * N; // 208
        bytes memory roots = new bytes(K * N);
        for (uint256 i = 0; i < K; i++) {
            uint256 idx = _forsIndex(md, i); // a-bit index
            uint256 base = i * perTree;
            bytes memory node = th(pkSeed, _forsLeafAdrs(a, i, idx), _slice(sigFors, base, N));

            uint256 authOff = base + N;
            uint256 treeIndex = i * (1 << A) + idx;
            for (uint256 j = 0; j < A; j++) {
                Adrs memory ha = a;
                ha.typ = FORS_TREE;
                ha.chainHeight = uint32(j + 1); // tree height
                ha.hash = 0;
                bytes memory auth = _slice(sigFors, authOff + j * N, N);
                if ((idx >> j) & 1 == 0) {
                    treeIndex = treeIndex / 2;
                    ha.treeIndex = uint32(treeIndex);
                    node = th(pkSeed, ha, bytes.concat(node, auth));
                } else {
                    treeIndex = (treeIndex - 1) / 2;
                    ha.treeIndex = uint32(treeIndex);
                    node = th(pkSeed, ha, bytes.concat(auth, node));
                }
            }
            for (uint256 j = 0; j < N; j++) roots[i * N + j] = node[j];
        }
        Adrs memory pkAdrs = a;
        pkAdrs.typ = FORS_ROOTS;
        pkAdrs.chainHeight = 0; pkAdrs.treeIndex = 0; pkAdrs.hash = 0;
        return th(pkSeed, pkAdrs, roots);
    }

    function _forsLeafAdrs(Adrs memory a, uint256 i, uint256 idx) private pure returns (Adrs memory ha) {
        ha = a;
        ha.typ = FORS_TREE;
        ha.chainHeight = 0; // tree height 0
        ha.hash = 0;
        ha.treeIndex = uint32(i * (1 << A) + idx);
    }

    // FORS index i: a-bit big-endian value from md bit offset i*a.
    function _forsIndex(bytes memory md, uint256 i) private pure returns (uint256 out) {
        uint256 bitStart = i * A;
        for (uint256 b = 0; b < A; b++) {
            uint256 bit = bitStart + b;
            uint256 byteIdx = bit / 8;
            uint256 bitInByte = 7 - (bit % 8);
            uint256 v = (uint8(md[byteIdx]) >> bitInByte) & 1;
            out = (out << 1) | v;
        }
    }

    // ---- helpers ----
    function _slice(bytes memory b, uint256 off, uint256 len) private pure returns (bytes memory out) {
        out = new bytes(len);
        for (uint256 i = 0; i < len; i++) out[i] = b[off + i];
    }
    function _eq(bytes memory x, bytes memory y) private pure returns (bool) {
        if (x.length != y.length) return false;
        for (uint256 i = 0; i < x.length; i++) if (x[i] != y[i]) return false;
        return true;
    }
    function _toUint(bytes memory b, uint256 off, uint256 len) private pure returns (uint256 v) {
        for (uint256 i = 0; i < len; i++) v = (v << 8) | uint8(b[off + i]);
    }

    /// @notice Verify an SLH-DSA-SHA2-128s signature over a 32-byte digest.
    /// @param pk 32-byte public key (PK.seed(16) || PK.root(16))
    /// @param message the signed message (mu_v3 = 32 bytes)
    /// @param sig 7856-byte signature
    function verify(bytes memory pk, bytes memory message, bytes memory sig) internal view returns (bool) {
        if (pk.length != PK_LEN || sig.length != SIG_LEN) return false;
        bytes memory pkSeed = _slice(pk, 0, N);
        bytes memory pkRoot = _slice(pk, N, N);

        bytes memory r = _slice(sig, 0, N);
        uint256 forsLen = K * (A + 1) * N; // 2912
        bytes memory sigFors = _slice(sig, N, forsLen);
        bytes memory sigHT = _slice(sig, N + forsLen, sig.length - N - forsLen);

        // FIPS 205 pure-mode domain separation: the signed message is (0x00 || ctxLen(0) || M).
        // This matches the default noble sign/verify with an empty context, so the identical
        // signature verifies on-chain and off-chain.
        bytes memory m2 = bytes.concat(hex"0000", message);
        bytes memory digest = hMsg(r, pkSeed, pkRoot, m2);
        // md = digest[0:21]; idxTree = digest[21:28] mod 2^54; idxLeaf = digest[28:30] mod 2^9
        bytes memory md = _slice(digest, 0, 21);
        uint64 idxTree = uint64(_toUint(digest, 21, 7) % (uint256(1) << (H - HP)));
        uint32 idxLeaf = uint32(_toUint(digest, 28, 2) % (uint256(1) << HP));

        Adrs memory a;
        a.tree = idxTree;
        a.typ = FORS_TREE;
        a.keypair = idxLeaf;
        bytes memory forsPk = forsPkFromSig(sigFors, md, pkSeed, a);

        return htVerify(forsPk, sigHT, pkSeed, idxTree, idxLeaf, pkRoot);
    }
}

contracts/crypto/SlhDsaVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {SlhDsaSha2_128s} from "./SlhDsaSha2_128s.sol";

/// @title SlhDsaVerifier — external wrapper around the FIPS 205 SLH-DSA-SHA2-128s verifier.
/// @notice Deployed as its OWN contract so callers can invoke it with a bounded gas budget via
///         `try verifier.verify{gas: cap}(...)`. That is what makes the on-chain Lemniscate (LOS/
///         SLH-DSA) check BEST-EFFORT: if the ~24.6M-gas verification cannot fit in the caller's gas
///         budget, the external call runs out of gas and the caller CATCHES it, proceeding on the
///         Falcon signature(s) alone — the transfer is never blocked by Lemniscate gas. A present but
///         INVALID signature still returns false (the caller decides to reject), which is distinct
///         from an out-of-gas.
///
///         Pure hashing (SHA-256 precompile), no secret input, no state — safe to call statically.
contract SlhDsaVerifier {
    /// @param pk      32-byte SLH-DSA-SHA2-128s public key
    /// @param message the signed message (mu, 32 bytes)
    /// @param sig     7856-byte signature
    /// @return true iff the signature is valid; false for a well-formed-but-invalid signature or a
    ///         wrong-length input. Runs out of gas (revert) if given less than it needs — callers use
    ///         try/catch to treat that as "disregarded".
    function verify(bytes calldata pk, bytes calldata message, bytes calldata sig)
        external
        view
        returns (bool)
    {
        return SlhDsaSha2_128s.verify(pk, message, sig);
    }
}

contracts/diamond/Modifiers.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {AppStorage} from "./libraries/LibAppStorage.sol";
import {LibDiamond} from "./libraries/LibDiamond.sol";

error OnlyGuardian();
error OnlyCexGovernance();
error OnlyOwnerOrRekeyOperator();
error Paused();
error NotPaused();
error ReentrancyGuardReentrantCall();

// Reentrancy guard constants
uint256 constant _NOT_ENTERED = 1;
uint256 constant _ENTERED = 2;

/// @title Modifiers - Shared access-control modifiers for all Lemnicoin facets
/// @notice Every facet that needs AppStorage or access control should inherit this.
///         The first declared state variable is `AppStorage internal s` so that
///         all facets agree on the storage layout starting at slot 0.
contract Modifiers {
    AppStorage internal s;

    modifier onlyOwner() {
        LibDiamond.enforceIsContractOwner();
        _;
    }

    modifier onlyGuardian() {
        if (msg.sender != s.guardian) revert OnlyGuardian();
        _;
    }

    modifier onlyCexGovernance() {
        if (msg.sender != s.cexGovernanceSigner) revert OnlyCexGovernance();
        _;
    }

    /// @notice Allows either the diamond owner OR the dedicated rekey operator.
    ///         Used for attestor key rotation so automated rekey can continue
    ///         after ownership is transferred to a Gnosis Safe multisig.
    modifier onlyOwnerOrRekeyOperator() {
        if (msg.sender != LibDiamond.contractOwner() && msg.sender != s.rekeyOperator) {
            revert OnlyOwnerOrRekeyOperator();
        }
        _;
    }

    modifier whenNotPaused() {
        if (s.paused) revert Paused();
        _;
    }

    modifier whenPaused() {
        if (!s.paused) revert NotPaused();
        _;
    }

    /// @notice Prevents reentrancy attacks on functions that transfer ETH (M-04 fix)
    modifier nonReentrant() {
        // On first call, status is 0, which we treat as _NOT_ENTERED
        if (s.reentrancyStatus == _ENTERED) revert ReentrancyGuardReentrantCall();
        s.reentrancyStatus = _ENTERED;
        _;
        s.reentrancyStatus = _NOT_ENTERED;
    }
}

contracts/diamond/facets/RecoveryFacet.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {Modifiers} from "../Modifiers.sol";
import {AppStorage, QuantumKeyHashes, LibAppStorage} from "../libraries/LibAppStorage.sol";
import {LibERC20} from "../libraries/LibERC20.sol";
import {LibLemnicoin} from "../libraries/LibLemnicoin.sol";
import {ZeroRecipient, AttestationExpired, InvalidNonce, InvalidSaltLength, InvalidS2Length, FalconVerificationFailed, HolderFalconSig} from "../libraries/LibLemnicoin.sol";
import "../../crypto/LAIPOnCurve.sol";
import "../../falcon/IZKNOXEthFalcon.sol";
import {LibSlhEconomics} from "../libraries/LibSlhEconomics.sol";

error RecoveryFromSelf();
error QuantumKeysNotRegistered();
error QuantumKeyMismatch();
error ZeroAmount();

/// @title RecoveryFacet — Wallet recovery using quantum key hashes
/// @notice Allows recovering LEMNI from a compromised wallet when both
///         wallets share the same quantum key hashes.
contract RecoveryFacet is Modifiers {

    bytes32 private constant RECOVERY_TYPEHASH =
        keccak256("PQRecovery(address from,address recoveredBy,address to,uint256 amount,bytes32 quantumInputHash,uint256 nonce,uint256 deadline)");

    event RecoveryTransferExecuted(
        address indexed from, address indexed recoveredBy, address indexed to, uint256 amount, uint256 nonce
    );

    // =========================================================================
    // RECOVERY TRANSFER
    // =========================================================================

    /// @dev Protected by nonReentrant to prevent reentrancy via fee refund (M-04)
    ///
    ///      ATTESTOR-ONLY and therefore PERMANENTLY CLOSED — use `recoveryTransferDual`. That costs
    ///      the recoverer nothing: recovery already requires proving possession of `from`'s quantum
    ///      keys, which come from the same 48-word seed as `from`'s Falcon key, so whoever can
    ///      legitimately recover can produce `from`'s holder Falcon signature too.
    function recoveryTransfer(
        address from,
        address to,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32,
        LAIPOnCurve.LAIPPublicKey calldata laipPk
    ) external payable whenNotPaused nonReentrant returns (bool) {
        LibSlhEconomics.requireNotV3DowngradePair(s, from, msg.sender); // NO-DOWNGRADE (both sides)
        // First, so the reason this path refused is unambiguous — and so it costs nothing to find
        // out. The guard is on `from`, the wallet whose balance moves, not on the caller.
        LibLemnicoin.requireAttestorOnlyAllowed(s, from);

        _recoveryPreflight(from, to, amount, laipPk);

        if (block.timestamp > deadline) revert AttestationExpired();

        uint256 expectedNonce = s.pqAttestationNonce[from];
        if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);
        if (falconSalt40.length != 40) revert InvalidSaltLength(falconSalt40.length);
        if (falconS2_32.length != 32) revert InvalidS2Length(falconS2_32.length);

        bytes32 digest = _recoveryDigest(from, msg.sender, to, amount, quantumInputHash, nonce, deadline);

        bool valid = IZKNOXEthFalcon(s.falconVerifier).verify(
            abi.encodePacked(digest),
            falconSalt40,
            LibLemnicoin._toMemoryArray(falconS2_32),
            _getAttestorNtth()
        );
        if (!valid) revert FalconVerificationFailed();

        s.pqAttestationNonce[from] = nonce + 1;
        LibERC20._transfer(from, to, amount);

        emit RecoveryTransferExecuted(from, msg.sender, to, amount, nonce);
        return true;
    }

    /// @notice The same recovery, requiring BOTH the attestor's Falcon signature and the compromised
    ///         wallet's own over the identical `PQRecovery` digest.
    /// @dev The holder key belongs to `from` — the compromised wallet — not to the caller. That is
    ///      the correct binding: recovery moves `from`'s balance, so it is `from`'s key that must
    ///      authorise it, and the recoverer holds that key precisely because they hold the seed.
    ///      The digest still names `msg.sender` as `recoveredBy`, so a signature obtained for one
    ///      recovery cannot be replayed by a different recoverer.
    function recoveryTransferDual(
        address from,
        address to,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32,
        HolderFalconSig calldata holderSig,
        LAIPOnCurve.LAIPPublicKey calldata laipPk
    ) external payable whenNotPaused nonReentrant returns (bool) {
        LibSlhEconomics.requireNotV3DowngradePair(s, from, msg.sender); // NO-DOWNGRADE (both sides)
        _recoveryPreflight(from, to, amount, laipPk);

        bytes32 digest = _recoveryDigest(from, msg.sender, to, amount, quantumInputHash, nonce, deadline);
        LibLemnicoin.requireDualFalcon(from, digest, nonce, deadline, falconSalt40, falconS2_32, holderSig);

        LibERC20._transfer(from, to, amount);

        emit RecoveryTransferExecuted(from, msg.sender, to, amount, nonce);
        return true;
    }

    /// @dev Everything both recovery paths check before they diverge on which signatures they want.
    ///      Extracted so the two entrypoints cannot drift apart — and so the dual variant's extra
    ///      argument does not push either of them past the stack limit.
    function _recoveryPreflight(
        address from,
        address to,
        uint256 amount,
        LAIPOnCurve.LAIPPublicKey calldata laipPk
    ) internal {
        // LAIP on-chain verification against compromised wallet's stored commitment
        LibLemnicoin.requireLaipVerification(from, laipPk);
        LibLemnicoin.collectProtocolFee(amount);

        if (from == msg.sender) revert RecoveryFromSelf();

        QuantumKeyHashes storage fromKeys = s.quantumKeyHashes[from];
        QuantumKeyHashes storage callerKeys = s.quantumKeyHashes[msg.sender];

        if (!fromKeys.registered) revert QuantumKeysNotRegistered();
        if (!callerKeys.registered) revert QuantumKeysNotRegistered();

        if (fromKeys.laipQHash != callerKeys.laipQHash ||
            fromKeys.laipP0Hash != callerKeys.laipP0Hash ||
            fromKeys.mldsaPkHash != callerKeys.mldsaPkHash) {
            revert QuantumKeyMismatch();
        }

        if (to == address(0)) revert ZeroRecipient();
    }

    // =========================================================================
    // VIEW FUNCTIONS
    // =========================================================================

    function canRecoverFrom(address from, address recoveredBy) external view returns (bool) {
        QuantumKeyHashes storage fromKeys = s.quantumKeyHashes[from];
        QuantumKeyHashes storage callerKeys = s.quantumKeyHashes[recoveredBy];

        if (!fromKeys.registered || !callerKeys.registered) return false;

        return (fromKeys.laipQHash == callerKeys.laipQHash &&
                fromKeys.laipP0Hash == callerKeys.laipP0Hash &&
                fromKeys.mldsaPkHash == callerKeys.mldsaPkHash);
    }

    function computeRecoveryDigest(
        address from, address recoveredBy, address to, uint256 amount,
        bytes32 quantumInputHash, uint256 nonce, uint256 deadline
    ) external view returns (bytes32) {
        return _recoveryDigest(from, recoveredBy, to, amount, quantumInputHash, nonce, deadline);
    }

    // =========================================================================
    // INTERNAL
    // =========================================================================

    function _recoveryDigest(
        address from, address recoveredBy, address to, uint256 amount,
        bytes32 quantumInputHash, uint256 nonce, uint256 deadline
    ) internal view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(RECOVERY_TYPEHASH, from, recoveredBy, to, amount, quantumInputHash, nonce, deadline)
        );
        return keccak256(abi.encodePacked("\x19\x01", LibLemnicoin.domainSeparatorV4(), structHash));
    }

    function _getAttestorNtth() internal view returns (uint256[] memory) {
        uint256[] memory result = new uint256[](32);
        for (uint256 i = 0; i < 32; i++) {
            result[i] = s.attestorNtth[i];
        }
        return result;
    }
}

