// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

/// @title IDiamondCut - EIP-2535 Diamond Cut Interface
/// @notice Interface for adding, replacing, and removing facets and their functions
interface IDiamondCut {
    enum FacetCutAction {
        Add,
        Replace,
        Remove
    }

    struct FacetCut {
        address facetAddress;
        FacetCutAction action;
        bytes4[] functionSelectors;
    }

    /// @notice Add/replace/remove any number of functions and optionally execute a function with full access
    /// @param _diamondCut Contains the facet addresses and function selectors
    /// @param _init The address of the contract or facet to execute _calldata
    /// @param _calldata A function call, including function selector and arguments
    function diamondCut(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external;

    event DiamondCut(FacetCut[] _diamondCut, address _init, bytes _calldata);
}

contracts/diamond/libraries/LibAppStorag.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import "../../LAIPVerifier.sol";

/// @title LibAppStorage - Shared storage layout for Lemnicoin Diamond
/// @notice All facets share this single storage struct at slot 0.
///         NEVER reorder or remove fields — only append new fields at the end.
///         Changing field order will corrupt storage for deployed diamonds.

// =========================================================================
// STRUCT DEFINITIONS (used inside AppStorage mappings)
// =========================================================================

struct QuantumKeys {
    LAIPVerifier.LAIPPublicKey laip;
    bytes dilithiumPublicKey; // 2592 bytes
    bool bound;
}

struct QuantumKeyHashes {
    bytes32 laipQHash;      // keccak256(laipQx || laipQy)
    bytes32 laipP0Hash;     // keccak256(laipP0x || laipP0y)
    bytes32 mldsaPkHash;    // keccak256(mldsaPublicKey)
    bool registered;
}

struct VestingSchedule {
    uint256 totalAmount;
    uint256 unlocked;       // Not used — vesting calculated dynamically
    uint256 startTime;
    uint256 cliffDuration;
    uint256 vestingDuration;
}

struct PendingTransfer {
    address from;
    address to;
    uint256 amount;
    bytes32 txBodyHash;
    bytes dilithiumSignature;
    bytes laipSignature;
    uint256 feePaid;
    uint256 nonce;
    bool exists;
}

struct FalconEnvelope {
    bytes32 txHash;
    bytes32 laipPubKeyCommitment;
    bytes laipPublicKey;
    bytes laipSignature;
    bytes dilithiumSignature;
}

/// @notice Time-locked token grant that releases 100% at unlockDate
struct TimeLock {
    uint256 amount;
    uint256 unlockDate;
    bool active;
}

/// @notice M-of-N ring of holder Falcon keys governing one account ("Multi-Sig").
/// @dev Only keccak256 commitments of the member keys are stored (one slot each); the full
///      32-word NTT-domain keys travel in calldata at signing time and are checked against
///      these commitments, exactly like the single holderFalconCommitment.
struct RingConfig {
    bytes32[] memberCommitments; // keccak256(abi.encodePacked(uint256[32] ntth)) per member
    uint8 threshold;             // M — signatures required per operation
    bool registered;             // write-once ratchet, same as the other quantum keys
}

/// @notice LAIP-V3 quantum key registration (isogeny KEM curve + on-chain-verifiable SLH-DSA).
/// @dev Only hashes and a small parameter id live on chain; full keys travel in calldata at use
///      time and are checked against these commitments, exactly like the V1/V2 hashes.
struct LaipV3Keys {
    bytes32 curveHash;      // keccak256(enc(A_wallet)) — CSIDH public curve coefficient hash
    bytes32 slhdsaPkHash;   // keccak256(SLH-DSA-SHA2-128s public key) — the LOS/hash-based signer
    bytes32 mldsaPkHash;    // keccak256(ML-DSA-87 public key) — carried for C_own_v3 continuity
    bytes32 paramId;        // e.g. keccak256("laip-csidh-p1024") — versions the isogeny parameter set
    bool registered;        // write-once ratchet
}

// =========================================================================
// APP STORAGE — the single source of truth for all facets
// =========================================================================

struct AppStorage {
    // --- ERC20 ---
    mapping(address => uint256) balances;
    mapping(address => mapping(address => uint256)) allowances;
    uint256 totalSupply;
    string name;
    string symbol;

    // --- Pausable ---
    bool paused;

    // --- Access control ---
    address guardian;
    address cexGovernanceSigner;

    // --- Quantum key management ---
    mapping(address => QuantumKeys) quantumKeys;
    mapping(address => uint256) quantumNonce;
    mapping(address => bytes32) laipKeyCommitment;
    mapping(address => QuantumKeyHashes) quantumKeyHashes;
    mapping(address => bytes32) bindingChallenges;
    uint256 challengeNonce;

    // --- Dilithium verifier validation ---
    bool dilithiumVerifierValidated;
    bool dilithiumValidationGuardianApproval;

    // --- CEX whitelist ---
    mapping(address => bool) isWhitelistedCEX;
    bool cexBypassEnabled;
    bool pendingCexBypassState;
    uint256 pendingCexBypassEta;
    bool cexBypassGuardianApproval;
    bool cexBypassFuseActivated;
    address pendingCexGovernanceSigner;

    // --- Per-user CEX/DEX sessions ---
    mapping(address => mapping(address => uint256)) userCexSession;

    // --- Oracle ---
    address priceOracle;
    bool laipTransferEnabled;
    address pendingOracle;
    uint256 pendingOracleEta;
    bool oracleGuardianApproval;
    uint256 lastOracleUpdate;

    // --- External verifier references (DEPRECATED - C-01/C-02 audit) ---
    // These fields are kept for storage layout compatibility but are no longer used.
    // All transfers now use Falcon attestation via QuantumTransferFacet.
    address dualKeyVerifier;  // DEPRECATED: removed transferWithDualKeyProof
    address starkVerifier;    // DEPRECATED: removed transferWithStarkProof

    // --- Pending transfers ---
    mapping(bytes32 => PendingTransfer) pendingTransfers;

    // --- Deployment phase ---
    bool deploymentPhaseActive;
    mapping(address => VestingSchedule) vestingSchedules;

    // --- Falcon attestation (was FalconAttestation mixin) ---
    address falconVerifier;           // IZKNOXEthFalcon address
    uint256[32] attestorNtth;         // Attestor public key in NTT domain
    mapping(address => uint256) pqAttestationNonce;

    // --- Falcon governance (was FalconGovernance mixin) ---
    address governanceFalconVerifier; // IZKNOXEthFalcon address
    uint256[32] governanceAttestorNtth;
    bool governanceFalconInitialized;
    mapping(address => uint256) governanceNonce;

    // --- LAIP curve validation cache ---
    // Stores keccak256(x || y) after on-chain curve validation via validateLaipCurve().
    // Transfers check this cache - if Q not validated, transaction fails as forgery.
    mapping(address => bytes32) laipValidatedQHash;

    // --- Time-locked grants (added post-deployment) ---
    // Multiple time locks per beneficiary, indexed by lock ID
    mapping(address => mapping(uint256 => TimeLock)) timeLocks;
    mapping(address => uint256) timeLockCount;

    // --- Reentrancy guard (M-04 fix) ---
    uint256 reentrancyStatus;

    // --- DEX pool whitelist (always active, no toggle/fuse) ---
    // Whitelisted DEX pool/pair contracts can send LEMNI outbound (transfer)
    // and receive LEMNI inbound (transferFrom recipient check).
    // Security: LEMNI can only enter a pool through quantum-protected paths
    // (quantumApprove + transferFrom). approve() does NOT bypass for DEX pools.
    mapping(address => bool) isWhitelistedDEXPool;

    // --- Wallet whitelist (governance-controlled sender->recipient bypass) ---
    // Allows specific sender->recipient pairs to use transfer()/approve()
    // without quantum signatures. Enable/disable via 3-step governance.
    // Guardian can permanently disable via fuse.
    mapping(address => mapping(address => bool)) walletWhitelistPair;
    bool walletWhitelistEnabled;
    bool pendingWalletWhitelistState;
    bool pendingWalletWhitelistActive;
    bool walletWhitelistGuardianApproval;
    bool walletWhitelistFuseActivated;

    // --- Oracle disable/enable toggle ---
    // Stores the oracle address when fees are temporarily disabled via disablePriceOracle().
    // enablePriceOracle() restores priceOracle from this field.
    address savedPriceOracle;

    // --- Rekey operator (Safe migration support) ---
    // Dedicated address that can rotate attestor keys (with Falcon governance sig)
    // without needing to be the diamond owner. This allows automated key rotation
    // to continue after ownership is transferred to a Gnosis Safe multisig.
    address rekeyOperator;

    // --- Quantum-approved spender tracking ---
    // Set to true ONLY when quantumApprove() is called. transferFrom() checks
    // this to ensure the spender's allowance was set through the quantum-protected
    // path (Falcon attestation + LAIP verification), not via a pre-existing
    // allowance from the old approve() bypass bug.
    mapping(address => mapping(address => bool)) quantumApprovedSpender;

    // --- Circuit breaker (auto-pause on anomalous transfer volume) ---
    // Tracks rolling transfer volume in a time window. If cumulative volume
    // exceeds the threshold, the contract auto-pauses without governance action.
    // Normal unpause governance flow (owner + Falcon) resumes operations.
    uint256 circuitBreakerWindowStart;   // start timestamp of current window
    uint256 circuitBreakerWindowVolume;  // cumulative transfer volume in current window
    uint256 circuitBreakerThreshold;     // max volume before auto-pause (0 = disabled)
    uint256 circuitBreakerWindow;        // window duration in seconds (e.g., 3600 = 1 hour)

    // --- Circuit breaker exclusions (liquidity infrastructure) ---
    // Transfers where either `from` or `to` is in this set are NOT counted
    // toward circuit breaker volume. Typical entries: deployer wallet,
    // Uniswap router, NonfungiblePositionManager, pool addresses.
    mapping(address => bool) circuitBreakerExcluded;

    // --- V2 Ownership Commitment (BTC cross-chain anchor) ---
    // C_own = SHA-256(K_laip_public || K_dilithium_public || K_hashbased_public)
    // Once set (non-zero), CANNOT be changed — even by the wallet owner.
    // This is the core theft-protection invariant: an attacker who steals
    // the wallet private key cannot re-register different quantum keys.
    // Also serves as the cross-chain anchor for BTC wallet verification.
    mapping(address => bytes32) ownershipCommitment;

    // --- Holder Falcon key (attestor-free signing path) ---
    // keccak256(abi.encodePacked(uint256[32] ntth)) for the holder's OWN Falcon-512 key, derived
    // in the dApp from the same 48-word seed as their LAIP and ML-DSA keys. When the attestor
    // cannot be reached, the holder signs the identical attestation packet themselves and passes
    // the full ntth in calldata; the chain hashes it and compares against this commitment.
    //
    // Storing only the hash keeps registration to one slot. Set once and then IMMUTABLE — the same
    // one-way ratchet as the other quantum keys, so a stolen wallet key cannot swap in a new one.
    //
    // NOTE: appended at the END of AppStorage. Diamond storage is layout-sensitive; new fields must
    // only ever be added here, never inserted above.
    mapping(address => bytes32) holderFalconCommitment;

    // --- Attestor liveness gate (holder-only path time-lock) ---
    // The single-signature holder-only path (quantumTransferWithHolderKey) is an escape hatch for
    // when the attestor is unreachable. To make normal operation a TRUE 2-of-2, that path is kept
    // CLOSED while the attestor proves it is alive, and only OPENS after the attestor has been
    // silent for `holderOnlyOutageBlocks` blocks.
    //
    //   attestorHeartbeatSigner   — the EOA the attestor service uses to post heartbeats. Set by
    //                               the owner. Distinct from the attestor's Falcon key (attestorNtth)
    //                               so heartbeating never touches the signing key.
    //   attestorLastHeartbeatBlock — block.number of the most recent heartbeat.
    //   holderOnlyOutageBlocks     — N. If 0 the gate is DISABLED and the holder-only path is always
    //                               allowed (exactly the pre-upgrade behavior), so this upgrade is
    //                               non-breaking until the owner configures it.
    //
    // Appended at the END — never insert above this.
    address attestorHeartbeatSigner;
    uint256 attestorLastHeartbeatBlock;
    uint256 holderOnlyOutageBlocks;

    // --- Multi-Sig rings (M-of-N holder Falcon multisig) ---
    // A ring account's balance moves only with >= threshold member Falcon signatures over the same
    // EIP-712 digest, plus the attestor's signature while the attestor is provably live (the same
    // liveness gate the holder-only path uses). Ring accounts have their single-signature paths
    // (dual / holder-only / session / recovery) closed in LibLemnicoin.requireDualFalcon and
    // transferWithHolderFalconAttestationFrom.
    //
    //   ringConfig          — the write-once ring definition per account.
    //   ringBypassNonce     — replay protection for bypass declarations/cancellations.
    //   ringBypassMaturesAt — timestamp an M-signed "proceed without the attestor" declaration
    //                         matures (0 = none active). The escape for an attestor that heartbeats
    //                         but refuses to co-sign; guarantees a ring is never frozen by us.
    //   ringBypassDelaySeconds — owner-set maturation delay (0 = use the 7-day default).
    //
    // Appended at the END — never insert above this.
    mapping(address => RingConfig) ringConfig;
    mapping(address => uint256) ringBypassNonce;
    mapping(address => uint256) ringBypassMaturesAt;
    uint256 ringBypassDelaySeconds;

    // --- LAIP-V3: isogeny KEM + hash-based (LOS/SLH-DSA) quantum keys ---
    // V3 is strictly ADDITIVE. Legacy V1/V2 registration (quantumKeyHashes, ownershipCommitment,
    // laipKeyCommitment) is preserved untouched, so a V3-migrated wallet can ALWAYS still transact
    // on its existing V1/V2 + dual-Falcon path — funds are never frozen by adopting V3.
    //
    //   laipV3          — per-account V3 key registration (see LaipV3Keys). Write-once ratchet.
    //   ownershipCommitmentV3 — C_own_v3 = keccak256(curveHash || mldsaPkHash || slhdsaPkHash),
    //                           the V3 hash-based-inclusive ownership anchor. Legacy `ownershipCommitment`
    //                           (the BTC cross-chain anchor) is DELIBERATELY left in place and readable
    //                           forever; BTC tooling adopts C_own_v3 on its own schedule.
    //
    // Appended at the END — never insert above this.
    mapping(address => LaipV3Keys) laipV3;
    mapping(address => bytes32) ownershipCommitmentV3;

    // Controls whether the on-chain SLH-DSA (LOS / hash family) is REQUIRED on the attestor-independent
    // path. Default false = STRICT: every such transfer must present a valid SLH signature that verifies
    // on chain, or it reverts — so the transfer always requires Falcon AND the hash family (immune to a
    // Falcon/lattice break). Owner sets this true ONLY on a chain whose blocks genuinely cannot fit the
    // ~24.6M-gas verification; there the path relaxes to best-effort/Falcon-only. This is a deliberate
    // per-chain governance decision, NOT an attacker-triggerable per-transaction skip.
    bool laipV3RelaxSlh;

    // Address of the external SlhDsaVerifier contract, called with a bounded gas budget so an
    // out-of-gas in the ~24.6M verification is caught and the transfer proceeds on Falcon. If zero,
    // the on-chain SLH-DSA check is skipped entirely (Falcon-only). Set by the owner post-deploy.
    address slhDsaVerifier;

    // --- LAIP-V3 ECONOMIC SLH EXEMPTION (the "1% rule") ---
    // A strict on-chain SLH-DSA verify costs ~24.6M gas. On a small transfer that gas can be worth
    // more than the value being moved, so the holder is made to pay more for the hash-family factor
    // than the factor protects. When that is true the factor is dropped and the transfer proceeds on
    // the Falcon floor.
    //
    // The rule is deliberately gated by an ORACLE-INDEPENDENT ceiling, because the value half of the
    // comparison comes from PriceOracle, whose LEMNI leg is a Uniswap V3 SPOT price and is therefore
    // manipulable inside a single block. The ceiling means no amount of price manipulation, and no
    // amount of basefee inflation, can widen the exemption past a fixed number of LEMNI per window.
    //
    //   slhExemptMaxAmount   — EXPLICIT governance ceiling, in LEMNI wei, on (a) any single exempt
    //                          transfer and (b) the rolling per-account total moved without on-chain
    //                          SLH. 0 = use the self-calibrating default (see LibSlhEconomics
    //                          .effectiveCeiling): the break-even amount under the live oracle,
    //                          clamped by totalSupply / DEFAULT_SUPPLY_DIVISOR so a manipulated
    //                          price cannot widen it. The rule is therefore ON by default.
    //   slhExemptDisabled    — governance kill switch for the whole economic exemption. false by
    //                          default, i.e. the rule is active. Setting it true restores the
    //                          pre-1%-rule behaviour: SLH required wherever the chain fits it.
    //   slhExemptWindow      — length of the rolling window in seconds. 0 = 1 day.
    //   slhExemptWindowStart — per-account start of the current window.
    //   slhExemptUsed        — per-account LEMNI wei moved without on-chain SLH in the current window.
    //
    // Appended at the END — never insert above this.
    uint256 slhExemptMaxAmount;
    uint256 slhExemptWindow;
    mapping(address => uint256) slhExemptWindowStart;
    mapping(address => uint256) slhExemptUsed;
    bool slhExemptDisabled;

    // --- Protocol fee exemption (per-wallet, governance-controlled) ---
    // Wallets in this set pay NO native protocol fee (the 12-40 bps collected in native
    // POL/ETH as msg.value) on ANY quantum transfer/approve/recovery path. This is the
    // blanket per-wallet counterpart to the pair-based walletWhitelist: it only ever SKIPS
    // the fee, never gates a transfer, so it can never freeze funds. Defaults to false for
    // every address (non-breaking). Managed by the owner via FeeExemptionFacet.setFeeExempt.
    //
    // SECURITY NOTE: the fee is protocol REVENUE, not a fund-safety control. Exempting a
    // wallet costs the protocol fee income on that wallet's transfers and nothing more; it
    // cannot be used to move another account's funds or bypass any quantum signature.
    //
    // Appended at the END — never insert above this.
    mapping(address => bool) feeExempt;

    // --- Circuit breaker: count each token once per window ---
    // Tokens a wallet RECEIVED in a counted transfer during the current breaker window were
    // already counted when they moved. When that wallet sends them on (onward, back, or
    // around a ring of wallets) they are not counted again, so cycling LEMNI between wallets
    // can never add more to the window volume than the tokens actually moved.
    // cbReceivedWindow[a] is the window start the cbReceived[a] figure belongs to; any other
    // value means "nothing received this window" (stale entries are ignored, never cleared).
    // Appended at the END — never insert above this.
    mapping(address => uint256) cbReceivedWindow;
    mapping(address => uint256) cbReceived;
}

// =========================================================================
// CONSTANTS (not stored — compiled into bytecode)
// =========================================================================

uint256 constant MAX_SUPPLY = 1_000_000_000 * 10 ** 18;

// Session duration limits (audit fix #6: reduced from 24h to 4h to limit exposure window)
// SECURITY: Even with a valid session, attackers only have a 4-hour window if they
// compromise a session. Users should create sessions only when actively trading.
uint256 constant MAX_SESSION_DURATION = 4 hours;
uint256 constant MIN_SESSION_DURATION = 5 minutes;

uint256 constant ORACLE_UPDATE_DELAY = 1 days;
uint256 constant ORACLE_UPDATE_COOLDOWN = 1 hours;

// CEX bypass requires 1-day timelock + guardian approval (defense in depth)
// SECURITY: cexBypassEnabled defaults to false. Once cexBypassFuseActivated is set,
// CEX bypass can NEVER be re-enabled (permanent shutdown via guardian fuse).
uint256 constant CEX_BYPASS_DELAY = 1 days;

uint256 constant PENDING_TRANSFER_TIMEOUT = 100;

library LibAppStorage {
    /// @notice Returns the AppStorage struct at slot 0.
    ///         All facets MUST use this (or declare `AppStorage internal s;`
    ///         as their first state variable) so they agree on layout.
    function appStorage() internal pure returns (AppStorage storage s) {
        assembly {
            s.slot := 0
        }
    }
}

contracts/diamond/libraries/LibDiamond.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import "../interfaces/IDiamondCut.sol";

error InitializationFunctionReverted(address _initializationContractAddress, bytes _calldata);
error NotDiamondOwner();
error NoSelectorsInFacetCut();
error FunctionAlreadyExists(bytes4 selector);
error FunctionDoesNotExist(bytes4 selector);
error FacetAddressIsZero();
error FacetAddressIsNotZero();
error FacetHasNoCode(address facet);
error IncorrectFacetCutAction();

/// @title LibDiamond - Core diamond proxy storage and logic
/// @notice Stores facet-to-selector mappings at a keccak256 slot,
///         separate from AppStorage at slot 0.
library LibDiamond {
    bytes32 constant DIAMOND_STORAGE_POSITION = keccak256("diamond.standard.diamond.storage");

    struct FacetAddressAndPosition {
        address facetAddress;
        uint96 functionSelectorPosition; // position in facetFunctionSelectors.functionSelectors array
    }

    struct FacetFunctionSelectors {
        bytes4[] functionSelectors;
        uint256 facetAddressPosition; // position in facetAddresses array
    }

    struct DiamondStorage {
        // maps function selector to the facet address and
        // the position of the selector in the facetFunctionSelectors.functionSelectors array
        mapping(bytes4 => FacetAddressAndPosition) selectorToFacetAndPosition;
        // maps facet addresses to function selectors
        mapping(address => FacetFunctionSelectors) facetFunctionSelectors;
        // facet addresses
        address[] facetAddresses;
        // Used to query if a contract implements an interface.
        // Used to implement ERC-165.
        mapping(bytes4 => bool) supportedInterfaces;
        // owner of the contract
        address contractOwner;
    }

    event DiamondCut(IDiamondCut.FacetCut[] _diamondCut, address _init, bytes _calldata);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    function diamondStorage() internal pure returns (DiamondStorage storage ds) {
        bytes32 position = DIAMOND_STORAGE_POSITION;
        assembly {
            ds.slot := position
        }
    }

    function setContractOwner(address _newOwner) internal {
        DiamondStorage storage ds = diamondStorage();
        address previousOwner = ds.contractOwner;
        ds.contractOwner = _newOwner;
        emit OwnershipTransferred(previousOwner, _newOwner);
    }

    function contractOwner() internal view returns (address contractOwner_) {
        contractOwner_ = diamondStorage().contractOwner;
    }

    function enforceIsContractOwner() internal view {
        if (msg.sender != diamondStorage().contractOwner) {
            revert NotDiamondOwner();
        }
    }

    // Internal function version of diamondCut
    function diamondCut(
        IDiamondCut.FacetCut[] memory _diamondCut,
        address _init,
        bytes memory _calldata
    ) internal {
        for (uint256 facetIndex; facetIndex < _diamondCut.length; facetIndex++) {
            IDiamondCut.FacetCutAction action = _diamondCut[facetIndex].action;
            if (action == IDiamondCut.FacetCutAction.Add) {
                addFunctions(
                    _diamondCut[facetIndex].facetAddress,
                    _diamondCut[facetIndex].functionSelectors
                );
            } else if (action == IDiamondCut.FacetCutAction.Replace) {
                replaceFunctions(
                    _diamondCut[facetIndex].facetAddress,
                    _diamondCut[facetIndex].functionSelectors
                );
            } else if (action == IDiamondCut.FacetCutAction.Remove) {
                removeFunctions(
                    _diamondCut[facetIndex].facetAddress,
                    _diamondCut[facetIndex].functionSelectors
                );
            } else {
                revert IncorrectFacetCutAction();
            }
        }
        emit DiamondCut(_diamondCut, _init, _calldata);
        initializeDiamondCut(_init, _calldata);
    }

    function addFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        if (_functionSelectors.length == 0) revert NoSelectorsInFacetCut();
        DiamondStorage storage ds = diamondStorage();
        if (_facetAddress == address(0)) revert FacetAddressIsZero();
        uint96 selectorPosition = uint96(
            ds.facetFunctionSelectors[_facetAddress].functionSelectors.length
        );
        // add new facet address if it does not exist
        if (selectorPosition == 0) {
            addFacet(ds, _facetAddress);
        }
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds
                .selectorToFacetAndPosition[selector]
                .facetAddress;
            if (oldFacetAddress != address(0)) revert FunctionAlreadyExists(selector);
            addFunction(ds, selector, selectorPosition, _facetAddress);
            selectorPosition++;
        }
    }

    function replaceFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        if (_functionSelectors.length == 0) revert NoSelectorsInFacetCut();
        DiamondStorage storage ds = diamondStorage();
        if (_facetAddress == address(0)) revert FacetAddressIsZero();
        uint96 selectorPosition = uint96(
            ds.facetFunctionSelectors[_facetAddress].functionSelectors.length
        );
        // add new facet address if it does not exist
        if (selectorPosition == 0) {
            addFacet(ds, _facetAddress);
        }
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds
                .selectorToFacetAndPosition[selector]
                .facetAddress;
            if (oldFacetAddress == _facetAddress) {
                revert FunctionAlreadyExists(selector);
            }
            if (oldFacetAddress == address(0)) revert FunctionDoesNotExist(selector);
            removeFunction(ds, oldFacetAddress, selector);
            addFunction(ds, selector, selectorPosition, _facetAddress);
            selectorPosition++;
        }
    }

    function removeFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
        if (_functionSelectors.length == 0) revert NoSelectorsInFacetCut();
        DiamondStorage storage ds = diamondStorage();
        // _facetAddress must be address(0) for Remove action
        if (_facetAddress != address(0)) revert FacetAddressIsNotZero();
        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
            bytes4 selector = _functionSelectors[selectorIndex];
            address oldFacetAddress = ds
                .selectorToFacetAndPosition[selector]
                .facetAddress;
            if (oldFacetAddress == address(0)) revert FunctionDoesNotExist(selector);
            removeFunction(ds, oldFacetAddress, selector);
        }
    }

    function addFacet(DiamondStorage storage ds, address _facetAddress) internal {
        enforceHasContractCode(_facetAddress);
        ds.facetFunctionSelectors[_facetAddress].facetAddressPosition = ds
            .facetAddresses
            .length;
        ds.facetAddresses.push(_facetAddress);
    }

    function addFunction(
        DiamondStorage storage ds,
        bytes4 _selector,
        uint96 _selectorPosition,
        address _facetAddress
    ) internal {
        ds
            .selectorToFacetAndPosition[_selector]
            .functionSelectorPosition = _selectorPosition;
        ds.selectorToFacetAndPosition[_selector].facetAddress = _facetAddress;
        ds
            .facetFunctionSelectors[_facetAddress]
            .functionSelectors
            .push(_selector);
    }

    function removeFunction(
        DiamondStorage storage ds,
        address _facetAddress,
        bytes4 _selector
    ) internal {
        // get selector position in array
        uint256 selectorPosition = ds
            .selectorToFacetAndPosition[_selector]
            .functionSelectorPosition;
        uint256 lastSelectorPosition = ds
            .facetFunctionSelectors[_facetAddress]
            .functionSelectors
            .length - 1;
        // if not the last selector, swap with last and pop
        if (selectorPosition != lastSelectorPosition) {
            bytes4 lastSelector = ds
                .facetFunctionSelectors[_facetAddress]
                .functionSelectors[lastSelectorPosition];
            ds.facetFunctionSelectors[_facetAddress].functionSelectors[
                    selectorPosition
                ] = lastSelector;
            ds
                .selectorToFacetAndPosition[lastSelector]
                .functionSelectorPosition = uint96(selectorPosition);
        }
        // delete the last selector
        ds.facetFunctionSelectors[_facetAddress].functionSelectors.pop();
        delete ds.selectorToFacetAndPosition[_selector];

        // if no more selectors for facet address then delete the facet address
        if (lastSelectorPosition == 0) {
            // replace facet address with last facet address and delete last facet address
            uint256 lastFacetAddressPosition = ds.facetAddresses.length - 1;
            uint256 facetAddressPosition = ds
                .facetFunctionSelectors[_facetAddress]
                .facetAddressPosition;
            if (facetAddressPosition != lastFacetAddressPosition) {
                address lastFacetAddress = ds.facetAddresses[
                    lastFacetAddressPosition
                ];
                ds.facetAddresses[facetAddressPosition] = lastFacetAddress;
                ds
                    .facetFunctionSelectors[lastFacetAddress]
                    .facetAddressPosition = facetAddressPosition;
            }
            ds.facetAddresses.pop();
            delete ds
                .facetFunctionSelectors[_facetAddress]
                .facetAddressPosition;
        }
    }

    function initializeDiamondCut(address _init, bytes memory _calldata) internal {
        if (_init == address(0)) {
            return;
        }
        enforceHasContractCode(_init);
        (bool success, bytes memory error) = _init.delegatecall(_calldata);
        if (!success) {
            if (error.length > 0) {
                // bubble up error
                assembly {
                    let returndata_size := mload(error)
                    revert(add(32, error), returndata_size)
                }
            } else {
                revert InitializationFunctionReverted(_init, _calldata);
            }
        }
    }

    function enforceHasContractCode(address _contract) internal view {
        uint256 contractSize;
        assembly {
            contractSize := extcodesize(_contract)
        }
        if (contractSize == 0) revert FacetHasNoCode(_contract);
    }
}

contracts/diamond/libraries/LibERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {AppStorage, VestingSchedule, TimeLock, LibAppStorage} from "./LibAppStorage.sol";

error ERC20TransferFromZero();
error ERC20TransferToZero();
error ERC20InsufficientBalance(address sender, uint256 balance, uint256 needed);
error ERC20ApproveFromZero();
error ERC20ApproveToZero();
error ERC20InsufficientAllowance(address spender, uint256 allowance, uint256 needed);
error ERC20MintToZero();
error ERC20BurnFromZero();
error ERC20BurnExceedsBalance(address account, uint256 balance, uint256 amount);
error TokensLocked();

/// @title LibERC20 - Internal ERC20 operations for Diamond facets
/// @notice Replicates OpenZeppelin ERC20 internal logic using AppStorage.
///         All state-changing ERC20 helpers live here so that any facet
///         can call them without code duplication.
library LibERC20 {
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event CircuitBreakerTripped(uint256 volumeInWindow, uint256 threshold, uint256 windowStart);

    function _transfer(address from, address to, uint256 amount) internal {
        if (from == address(0)) revert ERC20TransferFromZero();
        if (to == address(0)) revert ERC20TransferToZero();

        AppStorage storage s = LibAppStorage.appStorage();

        _beforeTokenTransfer(s, from, to, amount);

        uint256 fromBalance = s.balances[from];
        if (fromBalance < amount) revert ERC20InsufficientBalance(from, fromBalance, amount);
        unchecked {
            s.balances[from] = fromBalance - amount;
            s.balances[to] += amount;
        }

        emit Transfer(from, to, amount);
    }

    function _mint(address to, uint256 amount) internal {
        if (to == address(0)) revert ERC20MintToZero();

        AppStorage storage s = LibAppStorage.appStorage();

        _beforeTokenTransfer(s, address(0), to, amount);

        s.totalSupply += amount;
        unchecked {
            s.balances[to] += amount;
        }

        emit Transfer(address(0), to, amount);
    }

    function _burn(address from, uint256 amount) internal {
        if (from == address(0)) revert ERC20BurnFromZero();

        AppStorage storage s = LibAppStorage.appStorage();

        _beforeTokenTransfer(s, from, address(0), amount);

        uint256 balance = s.balances[from];
        if (balance < amount) revert ERC20BurnExceedsBalance(from, balance, amount);
        unchecked {
            s.balances[from] = balance - amount;
            s.totalSupply -= amount;
        }

        emit Transfer(from, address(0), amount);
    }

    function _approve(address owner_, address spender, uint256 amount) internal {
        if (owner_ == address(0)) revert ERC20ApproveFromZero();
        if (spender == address(0)) revert ERC20ApproveToZero();

        AppStorage storage s = LibAppStorage.appStorage();
        s.allowances[owner_][spender] = amount;

        emit Approval(owner_, spender, amount);
    }

    function _spendAllowance(address owner_, address spender, uint256 amount) internal {
        AppStorage storage s = LibAppStorage.appStorage();
        uint256 currentAllowance = s.allowances[owner_][spender];
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < amount) {
                revert ERC20InsufficientAllowance(spender, currentAllowance, amount);
            }
            unchecked {
                s.allowances[owner_][spender] = currentAllowance - amount;
            }
        }
    }

    /// @dev Mirrors the monolith's _beforeTokenTransfer: enforces pause + vesting + time locks + circuit breaker.
    function _beforeTokenTransfer(
        AppStorage storage s,
        address from,
        address to,
        uint256 amount
    ) private {
        // Pausable check
        require(!s.paused, "Pausable: paused");

        // Skip lock checks and circuit breaker for minting (from == address(0))
        if (from == address(0)) return;

        uint256 totalLocked = 0;

        // Vesting lock check
        VestingSchedule storage schedule = s.vestingSchedules[from];
        if (schedule.totalAmount > 0) {
            uint256 vested = _vestedAmount(schedule);
            totalLocked += schedule.totalAmount - vested;
        }

        // Time lock check
        uint256 timeLockCount = s.timeLockCount[from];
        for (uint256 i = 0; i < timeLockCount; i++) {
            TimeLock storage lock = s.timeLocks[from][i];
            if (lock.active && block.timestamp < lock.unlockDate) {
                totalLocked += lock.amount;
            }
        }

        // Ensure transfer doesn't exceed transferable balance
        if (totalLocked > 0) {
            uint256 transferable = s.balances[from] > totalLocked ? s.balances[from] - totalLocked : 0;
            if (amount > transferable) revert TokensLocked();
        }

        // Circuit breaker: track rolling transfer volume, auto-pause on anomaly.
        // Threshold of 0 means disabled (default for uninitialized storage).
        // Excluded addresses (liquidity infrastructure) are not counted, and neither are
        // self-transfers: they move nothing, and counting them let any wallet trip the breaker
        // (pausing every holder) by sending to itself in a loop.
        // Each token counts at most once per window: whatever the sender itself received in a
        // counted transfer during this window was already counted, so re-sending it (onward,
        // back to the original sender, or around a ring of fresh wallets) adds nothing.
        uint256 threshold = s.circuitBreakerThreshold;
        if (threshold > 0 && from != to && !s.circuitBreakerExcluded[from] && !s.circuitBreakerExcluded[to]) {
            uint256 window = s.circuitBreakerWindow;
            // If we've moved past the current window, start a new one
            if (block.timestamp >= s.circuitBreakerWindowStart + window) {
                s.circuitBreakerWindowStart = block.timestamp;
                s.circuitBreakerWindowVolume = 0;
            }
            uint256 windowStart = s.circuitBreakerWindowStart;

            // Portion of this transfer that was already counted on its way to `from`.
            uint256 fresh = amount;
            if (s.cbReceivedWindow[from] == windowStart) {
                uint256 already = s.cbReceived[from];
                uint256 reused = already < amount ? already : amount;
                s.cbReceived[from] = already - reused;
                fresh = amount - reused;
            }
            s.circuitBreakerWindowVolume += fresh;

            // Everything `to` receives here has now been counted once this window.
            if (s.cbReceivedWindow[to] == windowStart) {
                s.cbReceived[to] += amount;
            } else {
                s.cbReceivedWindow[to] = windowStart;
                s.cbReceived[to] = amount;
            }

            // If volume exceeds threshold, auto-pause. The triggering transfer
            // still completes (state is already committed), but all subsequent
            // transfers will hit the "Pausable: paused" check at the top.
            // This mirrors how real circuit breakers work: trip on the threshold
            // crossing, freeze everything after.
            if (s.circuitBreakerWindowVolume > threshold) {
                s.paused = true;
                emit CircuitBreakerTripped(
                    s.circuitBreakerWindowVolume,
                    threshold,
                    s.circuitBreakerWindowStart
                );
            }
        }
    }

    /// @dev Internal vesting calculation
    function _vestedAmount(VestingSchedule storage schedule) internal view returns (uint256) {
        if (schedule.totalAmount == 0) return 0;
        if (block.timestamp < schedule.startTime) return 0;

        uint256 elapsed = block.timestamp - schedule.startTime;

        // Before cliff: nothing vested
        if (elapsed < schedule.cliffDuration) return 0;

        // After cliff + vesting duration: fully vested
        uint256 vestingElapsed = elapsed - schedule.cliffDuration;
        if (vestingElapsed >= schedule.vestingDuration) {
            return schedule.totalAmount;
        }

        // During vesting: linear release
        return (schedule.totalAmount * vestingElapsed) / schedule.vestingDuration;
    }
}

contracts/diamond/libraries/LibLemnicoin.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {AppStorage, LibAppStorage} from "./LibAppStorage.sol";
import "../../PriceOracle.sol";
import "../../crypto/LAIPOnCurve.sol";
import "../../falcon/IZKNOXEthFalcon.sol";

error InsufficientFee();
error InvalidFeeCollector();
error FeeTransferFailed();
error RefundFailed();
error LAIPCommitmentMismatch();
error LAIPQHashMismatch();
error LAIPCurveNotValidated();
error QuantumKeysNotRegistered();
error AttestationExpired();
error InvalidNonce(uint256 expected, uint256 provided);
error InvalidSaltLength(uint256 length);
error InvalidS2Length(uint256 length);
error FalconVerificationFailed();
error ZeroRecipient();
error GovernanceNotInitialized();
error GovernanceAttestationExpired();
error GovernanceInvalidNonce(uint256 expected, uint256 provided);
error GovernanceInvalidSaltLength(uint256 length);
error GovernanceInvalidS2Length(uint256 length);
error GovernanceFalconVerificationFailed();
error HolderFalconKeyNotRegistered();
error InvalidNtthLength(uint256 length);
error HolderFalconKeyMismatch();
/// @notice The attestor's signature alone is no longer sufficient for this account, because it has
///         registered a Falcon key of its own. Use the `*Dual` entrypoint (attestor + holder) or,
///         if the attestor is unreachable, `quantumTransferWithHolderKey`.
/// @dev This is what converts "the holder CAN also sign" into "the holder MUST also sign". Without
///      it the attestor-only entrypoints stay open and a stolen attestor key still moves every
///      balance — the dual path would be advice rather than a control.
error AttestorOnlyPathClosed(address user);
/// @notice The holder's Falcon signature did not verify against their registered key.
error HolderFalconVerificationFailed();
/// @notice The single-signature holder-only path is time-locked shut because the attestor is still
///         proving liveness (heartbeating). It opens at `opensAtBlock` if the attestor stays silent
///         until then; use `quantumTransferDual` (attestor + holder) in the meantime.
error HolderOnlyPathTimeLocked(uint256 opensAtBlock);
/// @notice This account registered a Multi-Sig ring (M-of-N member keys), so every path that
///         accepts a SINGLE holder signature — dual, holder-only, session, recovery — is closed to
///         it. Use the ring entrypoints (RingTransferFacet), which require the member quorum.
/// @dev Without this closure the ring would be decorative: one member seed (or the account's old
///      single holder key) plus the attestor could bypass the quorum entirely.
error RingAccountMustUseRingPath(address account);

/// @notice A holder's own Falcon signature plus the public key it must verify against.
/// @dev Bundled into one struct rather than three loose parameters purely so the dual-signature
///      entrypoints stay inside Solidity's stack limits — `quantumTransfer` already carries eight
///      arguments including a struct.
struct HolderFalconSig {
    /// @notice Falcon salt (exactly 40 bytes).
    bytes salt40;
    /// @notice Falcon s2 (exactly 32 words).
    uint256[] s2_32;
    /// @notice The holder's Falcon public key in NTT domain (32 words), checked against the
    ///         commitment they registered. Supplied by the caller because storing 32 words per
    ///         holder is expensive; the commitment check is what binds it to the holder.
    uint256[] ntth;
}

/// @title LibLemnicoin - Shared helpers for Lemnicoin Diamond facets
/// @notice Contains Falcon attestation/governance helpers, LAIP verification,
///         protocol fee collection, EIP-712 domain separators, and tx-body hashing.
library LibLemnicoin {

    // =========================================================================
    // EVENTS
    // =========================================================================

    event ProtocolFeeCollected(address indexed from, address indexed collector, uint256 feeWei);
    event ExcessRefunded(address indexed to, uint256 amount);
    event FalconAttestationVerified(
        address indexed user, address indexed to, uint256 amount, uint256 nonce, bytes32 quantumInputHash
    );
    event GovernanceFalconVerified(address indexed signer, bytes32 actionHash, uint256 nonce);

    // =========================================================================
    // EIP-712 CONSTANTS
    // =========================================================================

    bytes32 private constant EIP712_DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant ATTEST_TYPEHASH =
        keccak256("PQAttestation(address user,address to,uint256 amount,bytes32 quantumInputHash,uint256 nonce,uint256 deadline)");
    bytes32 private constant APPROVAL_TYPEHASH =
        keccak256("PQApproval(address user,address spender,uint256 amount,bytes32 quantumInputHash,uint256 nonce,uint256 deadline)");
    bytes32 private constant NAME_HASH = keccak256("LemnicoinPQAttestation");
    bytes32 private constant VERSION_HASH = keccak256("1");

    bytes32 private constant GOV_EIP712_DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant GOV_ACTION_TYPEHASH =
        keccak256("GovernanceAction(address signer,bytes32 actionHash,uint256 nonce,uint256 deadline)");
    bytes32 private constant GOV_NAME_HASH = keccak256("LemnicoinGovernance");
    bytes32 private constant GOV_VERSION_HASH = keccak256("1");

    // =========================================================================
    // LAIP VERIFICATION
    // =========================================================================

    /// @notice Verify LAIP public key commitment and Q hash match validated keys
    /// @dev Curve validation must be done via validateLaipCurve() before first transfer.
    ///      This function only checks the Q matches what was validated on-chain.
    ///      If Q was never validated, transaction fails as forgery.
    function requireLaipVerification(
        address account,
        LAIPOnCurve.LAIPPublicKey calldata laipPk
    ) internal view {
        AppStorage storage s = LibAppStorage.appStorage();

        // Verify quantum keys are registered
        if (!s.quantumKeyHashes[account].registered) revert QuantumKeysNotRegistered();

        // Verify commitment matches (try both old and new formats)
        // New format: hash(x, y, P0x||P0y, a, p) where P0 contains both coordinates
        bytes32 commitmentNew = keccak256(
            abi.encodePacked(laipPk.x, laipPk.y, laipPk.P0, laipPk.a, laipPk.p)
        );

        // Old format: hash(x, y, P0x, a, p) where P0 only had P0x
        // P0 is 768 bytes (384*2), split it into P0x (first 384) and P0y (last 384)
        bytes memory P0x = new bytes(384);
        for (uint i = 0; i < 384; i++) {
            P0x[i] = laipPk.P0[i];
        }
        bytes32 commitmentOld = keccak256(
            abi.encodePacked(laipPk.x, laipPk.y, P0x, laipPk.a, laipPk.p)
        );

        // Accept either format
        if (s.laipKeyCommitment[account] != commitmentNew &&
            s.laipKeyCommitment[account] != commitmentOld) {
            revert LAIPCommitmentMismatch();
        }

        // Verify Q hash matches registered laipQHash
        bytes32 qHash = keccak256(abi.encodePacked(laipPk.x, laipPk.y));
        if (s.quantumKeyHashes[account].laipQHash != qHash) revert LAIPQHashMismatch();

        // Verify Q was validated on-chain via validateLaipCurve()
        // If not validated, this is a forgery attempt
        if (s.laipValidatedQHash[account] != qHash) revert LAIPCurveNotValidated();
    }

    // =========================================================================
    // PROTOCOL FEE COLLECTION
    // =========================================================================

    /// @notice Collect protocol fee; refund excess ETH
    /// @dev Fee-exempt wallets (s.feeExempt[msg.sender], set by governance via
    ///      FeeExemptionFacet) pay nothing: any native value they attached is refunded in
    ///      full and the function returns before the oracle is consulted. The exemption can
    ///      only ever WAIVE the fee — it never blocks a transfer, so it cannot freeze funds.
    function collectProtocolFee(uint256 amount) internal {
        AppStorage storage s = LibAppStorage.appStorage();

        // Per-wallet fee exemption: skip the fee entirely and refund any attached value.
        if (s.feeExempt[msg.sender]) {
            if (msg.value > 0) {
                (bool refundSuccess,) = msg.sender.call{value: msg.value}("");
                if (!refundSuccess) revert RefundFailed();
                emit ExcessRefunded(msg.sender, msg.value);
            }
            return;
        }

        if (s.priceOracle == address(0)) return;

        PriceOracle oracle = PriceOracle(s.priceOracle);
        uint256 requiredFee = oracle.getMinFeeInWei(amount);
        if (msg.value < requiredFee) revert InsufficientFee();

        address payable collector = oracle.feeCollector();

        if (requiredFee > 0 && collector != address(0)) {
            (bool feeSuccess,) = collector.call{value: requiredFee}("");
            if (!feeSuccess) revert FeeTransferFailed();
            emit ProtocolFeeCollected(msg.sender, collector, requiredFee);
        }

        uint256 excess = msg.value - requiredFee;
        if (excess > 0) {
            (bool refundSuccess,) = msg.sender.call{value: excess}("");
            if (!refundSuccess) revert RefundFailed();
            emit ExcessRefunded(msg.sender, excess);
        }
    }

    // =========================================================================
    // TX BODY HASH
    // =========================================================================

    function computeTxBodyHash(
        uint256 chainId,
        address from,
        address to,
        uint256 amount,
        uint256 nonce
    ) internal view returns (bytes32) {
        return keccak256(abi.encodePacked(chainId, address(this), from, to, amount, nonce));
    }

    function computeApprovalBodyHash(
        uint256 chainId,
        address owner_,
        address spender,
        uint256 amount,
        uint256 nonce
    ) internal view returns (bytes32) {
        return keccak256(abi.encodePacked(chainId, address(this), owner_, spender, amount, nonce));
    }

    // =========================================================================
    // FALCON ATTESTATION HELPERS
    // =========================================================================

    /// @notice EIP-712 domain separator for attestation
    function domainSeparatorV4() internal view returns (bytes32) {
        return keccak256(
            abi.encode(EIP712_DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, block.chainid, address(this))
        );
    }

    /// @notice Compute attestation digest for transfers
    function attestationDigest(
        address user,
        address to,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline
    ) internal view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(ATTEST_TYPEHASH, user, to, amount, quantumInputHash, nonce, deadline)
        );
        return keccak256(abi.encodePacked("\x19\x01", domainSeparatorV4(), structHash));
    }

    /// @notice Compute approval digest
    function approvalDigest(
        address user,
        address spender,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline
    ) internal view returns (bytes32) {
        bytes32 approvalStructHash = keccak256(
            abi.encode(APPROVAL_TYPEHASH, user, spender, amount, quantumInputHash, nonce, deadline)
        );
        return keccak256(abi.encodePacked("\x19\x01", domainSeparatorV4(), approvalStructHash));
    }

    /// @notice Verify Falcon attestation and execute transfer.
    /// @dev ATTESTOR-ONLY, and therefore closed to any account that has registered a Falcon key of
    ///      its own — those must use the dual-signature entrypoint (or the holder-only one during an
    ///      attestor outage). See `requireAttestorOnlyAllowed` for why this is conditional.
    function transferWithFalconAttestationFrom(
        address sender,
        address to,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32
    ) internal returns (bool) {
        AppStorage storage s = LibAppStorage.appStorage();

        if (to == address(0)) revert ZeroRecipient();
        if (block.timestamp > deadline) revert AttestationExpired();
        requireAttestorOnlyAllowed(s, sender);

        uint256 expectedNonce = s.pqAttestationNonce[sender];
        if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);
        if (falconSalt40.length != 40) revert InvalidSaltLength(falconSalt40.length);
        if (falconS2_32.length != 32) revert InvalidS2Length(falconS2_32.length);

        bytes32 digest = attestationDigest(sender, to, amount, quantumInputHash, nonce, deadline);

        bool valid = IZKNOXEthFalcon(s.falconVerifier).verify(
            abi.encodePacked(digest),
            falconSalt40,
            _toMemoryArray(falconS2_32),
            _getAttestorNtth(s)
        );
        if (!valid) revert FalconVerificationFailed();

        s.pqAttestationNonce[sender] = nonce + 1;

        emit FalconAttestationVerified(sender, to, amount, nonce, quantumInputHash);
        return true;
    }

    /// @notice Same transfer, authorised by the SENDER'S OWN Falcon key instead of the attestor's.
    /// @dev The attestor-free path. The digest, nonce, deadline and verifier are identical to
    ///      transferWithFalconAttestationFrom — only the key that signed differs, so a packet the
    ///      dApp built for the attestor can be re-signed locally and submitted here unchanged.
    ///
    ///      The holder's public key is not stored on-chain (32 words is expensive); only a hash of
    ///      it is, at registration. The caller supplies the full key here and it is checked against
    ///      that commitment, so this can only ever verify against the key the holder registered.
    ///
    ///      SECURITY: `holderNtth` comes from calldata, so the commitment check is what binds it to
    ///      the sender. Without a registered commitment there is no fallback path at all.
    function transferWithHolderFalconAttestationFrom(
        address sender,
        address to,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32,
        uint256[] calldata holderNtth
    ) internal returns (bool) {
        AppStorage storage s = LibAppStorage.appStorage();

        if (to == address(0)) revert ZeroRecipient();
        if (block.timestamp > deadline) revert AttestationExpired();
        // A ring account's outage path is "threshold member signatures, no attestor" on the ring
        // entrypoints — never a single holder key. Checked before anything else so a probing call
        // learns the real reason.
        requireNotRingAccount(s, sender);

        uint256 expectedNonce = s.pqAttestationNonce[sender];
        if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);
        if (falconSalt40.length != 40) revert InvalidSaltLength(falconSalt40.length);
        if (falconS2_32.length != 32) revert InvalidS2Length(falconS2_32.length);

        _requireHolderFalconKey(s, sender, holderNtth);

        bytes32 digest = attestationDigest(sender, to, amount, quantumInputHash, nonce, deadline);

        bool valid = IZKNOXEthFalcon(s.falconVerifier).verify(
            abi.encodePacked(digest),
            falconSalt40,
            _toMemoryArray(falconS2_32),
            _toMemoryArray(holderNtth)
        );
        if (!valid) revert FalconVerificationFailed();

        s.pqAttestationNonce[sender] = nonce + 1;

        emit FalconAttestationVerified(sender, to, amount, nonce, quantumInputHash);
        return true;
    }

    /// @notice Holder-only APPROVAL: the sender's own Falcon key authorises an allowance, with no
    ///         attestor signature. The approval counterpart of transferWithHolderFalconAttestationFrom.
    /// @dev Added for the V3 attestor-independent approve (LAIPV3TransferFacet.quantumApproveV3).
    ///      V1/V2 deliberately had no holder-only approve, because a V1/V2 wallet always retained a
    ///      dual approve. A V3 wallet does not: the no-downgrade gate closes the legacy approve to
    ///      it, so without this helper an attestor outage would leave V3 wallets unable to grant an
    ///      allowance at all. Callers MUST apply the attestor-liveness gate
    ///      (requireHolderOnlyPathOpen) exactly as the holder-only transfer path does — this helper
    ///      does not open a permanent single-signature approve.
    ///      Ring accounts are excluded (single holder signature is insufficient authority for them),
    ///      the nonce is checked and burned here, and the holder key is bound to its commitment.
    function approveWithHolderFalconInternal(
        address sender,
        address spender,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        HolderFalconSig calldata holderSig
    ) internal returns (bool) {
        AppStorage storage s = LibAppStorage.appStorage();

        if (spender == address(0)) revert ZeroRecipient();
        if (block.timestamp > deadline) revert AttestationExpired();
        requireNotRingAccount(s, sender);

        uint256 expectedNonce = s.pqAttestationNonce[sender];
        if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);

        bytes32 digest = approvalDigest(sender, spender, amount, quantumInputHash, nonce, deadline);
        // Verifies salt/s2/ntth lengths, binds ntth to the registered commitment, and checks the
        // signature — the same helper every holder-Falcon path uses.
        verifyHolderFalcon(s, sender, digest, holderSig);

        s.pqAttestationNonce[sender] = nonce + 1;
        return true;
    }

    /// @notice Revert unless `holderNtth` is exactly the Falcon key `holder` registered.
    function _requireHolderFalconKey(
        AppStorage storage s,
        address holder,
        uint256[] calldata holderNtth
    ) internal view {
        if (holderNtth.length != 32) revert InvalidNtthLength(holderNtth.length);

        bytes32 commitment = s.holderFalconCommitment[holder];
        if (commitment == bytes32(0)) revert HolderFalconKeyNotRegistered();
        if (keccak256(abi.encodePacked(holderNtth)) != commitment) revert HolderFalconKeyMismatch();
    }

    // =========================================================================
    // DUAL SIGNATURE — the attestor's Falcon signature AND the holder's own
    // =========================================================================
    //
    // THE PROBLEM THIS SOLVES. Every attestor-signed entrypoint above treats one Falcon signature,
    // under one key held by one server, as the complete authority to move a user's balance. The
    // holder's own post-quantum keys are checked only OFF-chain, by that same server. So possession
    // of the attestor's private key was sufficient to move every balance, with no user involvement:
    // a universal spending key, and every piece of infrastructure hardening around it was an attempt
    // to keep one secret safe rather than to make losing it survivable.
    //
    // THE RULE. A holder who has registered a Falcon key must sign alongside the attestor. Both
    // signatures cover the SAME digest, so neither party can be shown a different transfer from the
    // one that executes, and an attacker holding the attestor's key alone can move nothing.
    //
    // PERMANENTLY CLOSED — attestor-only is disabled for EVERY account, unconditionally. Previously
    // this was conditional (open only until a holder registered a Falcon key) to avoid freezing
    // unregistered holders. That condition is now removed by design: the dApp derives and registers a
    // holder Falcon key at login, so every real account has one, and no legitimate flow needs an
    // attestor-only path. The attestor's signature alone must NEVER move funds — a compromised
    // attestor key would otherwise drain any account that had not yet registered.
    //
    // CONSEQUENCE (accepted): an account that holds funds but has never registered a holder Falcon key
    // cannot use any quantum path until it registers one via KeyManagementFacet.registerHolderFalconKey
    // (a normal transaction the dApp performs automatically at login/unlock). After that one-time
    // registration it transacts through the *Dual entrypoints, or quantumTransferWithHolderKey during
    // an attestor outage. This is not a permanent freeze — it makes "register your own Falcon key" a
    // hard prerequisite for spending, which is exactly the intent.

    /// @notice Revert on EVERY attestor-only entrypoint — the caller must instead co-sign with its own
    ///         Falcon key (the *Dual paths, or quantumTransferWithHolderKey).
    /// @dev The single chokepoint every attestor-only path calls, so the closure cannot be missed and
    ///      any future attestor-only entrypoint that routes through here is closed automatically. `s`
    ///      is unused now that the check is unconditional.
    function requireAttestorOnlyAllowed(AppStorage storage, address user) internal view {
        revert AttestorOnlyPathClosed(user);
    }

    /// @notice Revert if `user` has registered a Multi-Sig ring — single-holder-signature
    ///         paths are closed to ring accounts (see RingAccountMustUseRingPath).
    function requireNotRingAccount(AppStorage storage s, address user) internal view {
        if (s.ringConfig[user].registered) revert RingAccountMustUseRingPath(user);
    }


    // =========================================================================
    // ATTESTOR LIVENESS GATE — makes the holder-only path a true 2-of-2 fallback
    // =========================================================================
    // The holder-only path (quantumTransferWithHolderKey) is a single-signature escape hatch. On its
    // own it means the holder's key alone can always move funds, so the "dual" requirement is advice
    // rather than a control. This gate makes it a control: while the attestor heartbeats, the
    // holder-only path is CLOSED (every transfer must be dual = attestor + holder), and it OPENS only
    // after the attestor has been silent for `holderOnlyOutageBlocks` (N) blocks — a genuine outage.
    // N == 0 disables the gate (holder-only always allowed), which is the pre-upgrade behavior.

    /// @notice Whether the single-signature holder-only path is currently open.
    /// @dev Open iff the gate is disabled (N == 0) OR the attestor has gone silent for more than N
    ///      blocks. While the attestor heartbeats this is false, which is what forces the 2-of-2.
    function holderOnlyPathOpen(AppStorage storage s) internal view returns (bool) {
        uint256 n = s.holderOnlyOutageBlocks;
        if (n == 0) return true;
        return block.number > s.attestorLastHeartbeatBlock + n;
    }

    /// @notice Revert unless the holder-only path is open (see holderOnlyPathOpen).
    function requireHolderOnlyPathOpen(AppStorage storage s) internal view {
        uint256 n = s.holderOnlyOutageBlocks;
        if (n == 0) return;
        uint256 opensAtBlock = s.attestorLastHeartbeatBlock + n + 1; // first block the path is open
        if (block.number < opensAtBlock) revert HolderOnlyPathTimeLocked(opensAtBlock);
    }

    /// @notice Verify the holder's own Falcon signature over `digest` against their registered key.
    function verifyHolderFalcon(
        AppStorage storage s,
        address holder,
        bytes32 digest,
        HolderFalconSig calldata sig
    ) internal view {
        if (sig.salt40.length != 40) revert InvalidSaltLength(sig.salt40.length);
        if (sig.s2_32.length != 32) revert InvalidS2Length(sig.s2_32.length);
        if (sig.ntth.length != 32) revert InvalidNtthLength(sig.ntth.length);

        bytes32 commitment = s.holderFalconCommitment[holder];
        if (commitment == bytes32(0)) revert HolderFalconKeyNotRegistered();
        if (keccak256(abi.encodePacked(sig.ntth)) != commitment) revert HolderFalconKeyMismatch();

        bool valid = IZKNOXEthFalcon(s.falconVerifier).verify(
            abi.encodePacked(digest),
            sig.salt40,
            _toMemoryArray(sig.s2_32),
            _toMemoryArray(sig.ntth)
        );
        if (!valid) revert HolderFalconVerificationFailed();
    }

    /// @notice Verify the ATTESTOR's Falcon signature over `digest`.
    function verifyAttestorFalcon(
        AppStorage storage s,
        bytes32 digest,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32
    ) internal view {
        if (falconSalt40.length != 40) revert InvalidSaltLength(falconSalt40.length);
        if (falconS2_32.length != 32) revert InvalidS2Length(falconS2_32.length);

        bool valid = IZKNOXEthFalcon(s.falconVerifier).verify(
            abi.encodePacked(digest),
            falconSalt40,
            _toMemoryArray(falconS2_32),
            _getAttestorNtth(s)
        );
        if (!valid) revert FalconVerificationFailed();
    }

    /// @notice Shared tail of every dual-signature entrypoint: check the window and the nonce, then
    ///         require BOTH signatures over the one digest, then burn the nonce.
    /// @dev The order matters for diagnosis, not for safety — the attestor is checked first so an
    ///      attestor-side problem reverts with `FalconVerificationFailed` rather than being masked
    ///      by the holder's key. Both must pass regardless.
    function requireDualFalcon(
        address user,
        bytes32 digest,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32,
        HolderFalconSig calldata holderSig
    ) internal {
        AppStorage storage s = LibAppStorage.appStorage();

        // Every caller of this tail (dual transfer/approve/burn, SessionFacet, RecoveryFacet)
        // accepts ONE holder signature — insufficient authority for a ring account, whose quorum
        // is enforced only on the ring entrypoints. One check here closes them all.
        requireNotRingAccount(s, user);

        if (block.timestamp > deadline) revert AttestationExpired();
        uint256 expectedNonce = s.pqAttestationNonce[user];
        if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);

        verifyAttestorFalcon(s, digest, falconSalt40, falconS2_32);
        verifyHolderFalcon(s, user, digest, holderSig);

        s.pqAttestationNonce[user] = nonce + 1;
    }

    /// @notice Dual-signature transfer: identical to `transferWithFalconAttestationFrom` except that
    ///         the holder must sign the same digest as well.
    function transferWithDualFalconAttestationFrom(
        address sender,
        address to,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32,
        HolderFalconSig calldata holderSig
    ) internal returns (bool) {
        if (to == address(0)) revert ZeroRecipient();

        bytes32 digest = attestationDigest(sender, to, amount, quantumInputHash, nonce, deadline);
        requireDualFalcon(sender, digest, nonce, deadline, falconSalt40, falconS2_32, holderSig);

        emit FalconAttestationVerified(sender, to, amount, nonce, quantumInputHash);
        return true;
    }

    /// @notice Dual-signature approval.
    function approveWithDualFalconInternal(
        address sender,
        address spender,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32,
        HolderFalconSig calldata holderSig
    ) internal returns (bool) {
        if (spender == address(0)) revert ZeroRecipient();

        bytes32 digest = approvalDigest(sender, spender, amount, quantumInputHash, nonce, deadline);
        requireDualFalcon(sender, digest, nonce, deadline, falconSalt40, falconS2_32, holderSig);
        return true;
    }

    /// @notice Dual-signature burn. Reuses the transfer digest with `to = address(0)`, exactly as
    ///         the attestor-only burn does.
    function verifyDualFalconAttestationForBurn(
        address sender,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32,
        HolderFalconSig calldata holderSig
    ) internal returns (bool) {
        bytes32 digest = attestationDigest(sender, address(0), amount, quantumInputHash, nonce, deadline);
        requireDualFalcon(sender, digest, nonce, deadline, falconSalt40, falconS2_32, holderSig);

        emit FalconAttestationVerified(sender, address(0), amount, nonce, quantumInputHash);
        return true;
    }

    /// @notice Verify Falcon attestation for burn operations (allows address(0))
    function verifyFalconAttestationForBurn(
        address sender,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32
    ) internal returns (bool) {
        AppStorage storage s = LibAppStorage.appStorage();

        if (block.timestamp > deadline) revert AttestationExpired();
        requireAttestorOnlyAllowed(s, sender);

        uint256 expectedNonce = s.pqAttestationNonce[sender];
        if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);
        if (falconSalt40.length != 40) revert InvalidSaltLength(falconSalt40.length);
        if (falconS2_32.length != 32) revert InvalidS2Length(falconS2_32.length);

        // Use address(0) as "to" for burn digest
        bytes32 digest = attestationDigest(sender, address(0), amount, quantumInputHash, nonce, deadline);

        bool valid = IZKNOXEthFalcon(s.falconVerifier).verify(
            abi.encodePacked(digest),
            falconSalt40,
            _toMemoryArray(falconS2_32),
            _getAttestorNtth(s)
        );
        if (!valid) revert FalconVerificationFailed();

        s.pqAttestationNonce[sender] = nonce + 1;

        emit FalconAttestationVerified(sender, address(0), amount, nonce, quantumInputHash);
        return true;
    }

    /// @notice Internal Falcon approval
    function approveWithFalconInternal(
        address sender,
        address spender,
        uint256 amount,
        bytes32 quantumInputHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2_32
    ) internal returns (bool) {
        AppStorage storage s = LibAppStorage.appStorage();

        if (spender == address(0)) revert ZeroRecipient();
        if (block.timestamp > deadline) revert AttestationExpired();
        requireAttestorOnlyAllowed(s, sender);

        uint256 expectedNonce = s.pqAttestationNonce[sender];
        if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);
        if (falconSalt40.length != 40) revert InvalidSaltLength(falconSalt40.length);
        if (falconS2_32.length != 32) revert InvalidS2Length(falconS2_32.length);

        bytes32 digest = approvalDigest(sender, spender, amount, quantumInputHash, nonce, deadline);

        bool valid = IZKNOXEthFalcon(s.falconVerifier).verify(
            abi.encodePacked(digest),
            falconSalt40,
            _toMemoryArray(falconS2_32),
            _getAttestorNtth(s)
        );
        if (!valid) revert FalconVerificationFailed();

        s.pqAttestationNonce[sender] = nonce + 1;
        return true;
    }

    // =========================================================================
    // FALCON GOVERNANCE HELPERS
    // =========================================================================

    /// @notice EIP-712 domain separator for governance
    function govDomainSeparator() internal view returns (bytes32) {
        return keccak256(
            abi.encode(GOV_EIP712_DOMAIN_TYPEHASH, GOV_NAME_HASH, GOV_VERSION_HASH, block.chainid, address(this))
        );
    }

    /// @notice Compute governance action digest
    function governanceDigest(
        address signer,
        bytes32 actionHash,
        uint256 nonce,
        uint256 deadline
    ) internal view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(GOV_ACTION_TYPEHASH, signer, actionHash, nonce, deadline)
        );
        return keccak256(abi.encodePacked("\x19\x01", govDomainSeparator(), structHash));
    }

    /// @notice Verify Falcon governance attestation
    function requireFalconGovernance(
        address signer,
        string memory action,
        bytes memory payload,
        uint256 nonce,
        uint256 deadline,
        bytes calldata falconSalt40,
        uint256[] calldata falconS2
    ) internal {
        AppStorage storage s = LibAppStorage.appStorage();

        if (!s.governanceFalconInitialized) revert GovernanceNotInitialized();
        if (block.timestamp > deadline) revert GovernanceAttestationExpired();

        uint256 expectedNonce = s.governanceNonce[signer];
        if (nonce != expectedNonce) revert GovernanceInvalidNonce(expectedNonce, nonce);
        if (falconSalt40.length != 40) revert GovernanceInvalidSaltLength(falconSalt40.length);
        if (falconS2.length != 32) revert GovernanceInvalidS2Length(falconS2.length);

        bytes32 actionHash = keccak256(abi.encodePacked(action, payload));
        bytes32 digest = governanceDigest(signer, actionHash, nonce, deadline);

        bool valid = IZKNOXEthFalcon(s.governanceFalconVerifier).verify(
            abi.encodePacked(digest),
            falconSalt40,
            _govToMemoryArray(falconS2),
            _getGovAttestorNtth(s)
        );
        if (!valid) revert GovernanceFalconVerificationFailed();

        s.governanceNonce[signer] = nonce + 1;
        emit GovernanceFalconVerified(signer, actionHash, nonce);
    }

    // =========================================================================
    // ARRAY CONVERSION HELPERS
    // =========================================================================

    function _toMemoryArray(uint256[] calldata arr) internal pure returns (uint256[] memory) {
        uint256[] memory result = new uint256[](arr.length);
        for (uint256 i = 0; i < arr.length; i++) {
            result[i] = arr[i];
        }
        return result;
    }

    function _getAttestorNtth(AppStorage storage s) internal view returns (uint256[] memory) {
        uint256[] memory result = new uint256[](32);
        for (uint256 i = 0; i < 32; i++) {
            result[i] = s.attestorNtth[i];
        }
        return result;
    }

    function _govToMemoryArray(uint256[] calldata arr) internal pure returns (uint256[] memory) {
        uint256[] memory result = new uint256[](32);
        for (uint256 i = 0; i < 32 && i < arr.length; i++) {
            result[i] = arr[i];
        }
        return result;
    }

    function _getGovAttestorNtth(AppStorage storage s) internal view returns (uint256[] memory) {
        uint256[] memory result = new uint256[](32);
        for (uint256 i = 0; i < 32; i++) {
            result[i] = s.governanceAttestorNtth[i];
        }
        return result;
    }

    /// @notice Split a packed Falcon signature into salt and s2 components
    function splitFalconSig(bytes calldata falconSig)
        internal
        pure
        returns (bytes memory salt, uint256[] memory s2)
    {
        uint256 expectedLength = 40 + 32 * 32;
        require(falconSig.length == expectedLength, "Invalid Falcon signature length");

        salt = new bytes(40);
        for (uint256 i = 0; i < 40; i++) {
            salt[i] = falconSig[i];
        }

        s2 = new uint256[](32);
        for (uint256 i = 0; i < 32; i++) {
            uint256 offset = 40 + i * 32;
            uint256 value;
            assembly {
                value := calldataload(add(falconSig.offset, offset))
            }
            s2[i] = value;
        }
    }
}

contracts/diamond/libraries/LibSlhEconom.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {AppStorage, LaipV3Keys} from "./LibAppStorage.sol";
import {SlhDsaVerifier} from "../../crypto/SlhDsaVerifier.sol";

/// Declared at file scope so every V3 facet that uses this library reverts with the SAME custom
/// errors — clients decode one set of selectors regardless of which entrypoint they called.
error LaipV3SlhKeyMismatch();
error SlhDsaVerificationFailed();

/// THE NO-DOWNGRADE GATE's error. Raised when a V3-registered account calls a LEGACY (Falcon-only)
/// entrypoint while the chain is able to enforce the hash-family factor. The account is not stuck:
/// the V3 entrypoint for the same operation is, by the gate's own condition, guaranteed available.
error LaipV3LegacyPathClosed(address account);
import {PriceOracle} from "../../PriceOracle.sol";

/// @title LibSlhEconomics — THE ONE PLACE that decides when the SLH-DSA factor is required, and
///        the one place that verifies it. Every V3 facet routes through here so the rule cannot
///        drift between transfers, approvals, recovery, CEX sessions and burns.
///
/// The economic half of it is the "1% rule": never make a holder pay more for the hash-family factor
///        than the factor is protecting.
///
/// @notice A strict on-chain SLH-DSA verification costs ~1.2M gas with the optimized verifier
///         (SlhDsaVerifierV2), plus ~126k for the 7856-byte signature's calldata. On a large
///         transfer that is noise. On a small one it can still exceed the value being moved, which
///         would price ordinary users out of their own wallets. So when the on-chain cost of the
///         SLH factor exceeds `SLH_ECONOMIC_BPS` (1%) of the transfer's value, the factor is
///         dropped and the transfer proceeds on the Falcon floor (never make the security theatre
///         cost more than the asset).
///
/// ============================ WHY THIS CANNOT BE GAMED ============================
///
/// The exemption makes a transfer CHEAPER and WEAKER, so every input it reads is an attack surface.
/// Four independent locks, each of which alone denies the exemption:
///
///  1. COST IS PRICED FROM `block.basefee`, NEVER `tx.gasprice`.
///     `tx.gasprice` is chosen by the sender: an attacker would simply declare a 10,000 gwei gas
///     price, make the SLH "cost" astronomical, and skip the check on any transfer they liked.
///     `block.basefee` is set by the chain's own EIP-1559 consensus rule from the PREVIOUS block's
///     fullness. A sender cannot set it. Inflating it means filling many consecutive blocks at their
///     own expense — and lock 3 caps the payoff of doing so anyway.
///
///  2. AN ORACLE-INDEPENDENT ABSOLUTE CEILING, in LEMNI wei.
///     The value half of the comparison comes from PriceOracle, whose LEMNI leg is a Uniswap V3
///     SPOT price (`slot0`) and is therefore flash-loan manipulable within a single block. An
///     attacker could crush the pool price so that a large LEMNI amount reads as a few dollars and
///     "deserves" the exemption. The ceiling is denominated in LEMNI, not in value, so no price and
///     no basefee can ever exempt a transfer larger than it.
///
///     The rule is ON BY DEFAULT, so the ceiling has to size itself without a governance number.
///     `effectiveCeiling` computes `min(break-even amount under the live oracle, totalSupply /
///     DEFAULT_SUPPLY_DIVISOR)`. The first term is what the 1% rule itself already says is not
///     worth protecting, so under an honest oracle it never binds a legitimate transfer; the second
///     is a pure on-chain quantity an attacker cannot move, and is what a manipulated price runs
///     into. Governance may replace the whole thing with an explicit `slhExemptMaxAmount`, or turn
///     the exemption off with `slhExemptDisabled`.
///
///  3. A ROLLING PER-ACCOUNT BUDGET, charged in LEMNI, that defeats SPLITTING.
///     A per-transfer threshold on its own is trivially defeated by cutting one large drain into
///     many sub-threshold transfers. Every transfer that actually moves WITHOUT an on-chain SLH
///     verification is charged against a per-account rolling total, and once that total would exceed
///     the same ceiling the exemption is refused until the window rolls. So the ceiling bounds not
///     just one transfer but ALL SLH-free value an account can move per window. Splitting buys
///     nothing.
///
///  4. EVERY UNCERTAINTY FAILS CLOSED (to strict), never open.
///     Oracle unset, oracle reverting, a zero fee-bps, a zero derived value, or a zero basefee all
///     DENY the exemption. There is no input an attacker can suppress or corrupt into an exemption;
///     breaking the oracle only makes the chain stricter.
///
/// One residual, disclosed rather than hidden: a validator can nudge `block.timestamp` and so roll
/// the budget window slightly early. Consensus bounds that drift to seconds against a window of a
/// day, and the ceiling still applies to each window, so the effect is negligible.
///
/// Note what the exemption is NOT: it never touches the Falcon floor. A transfer that takes the
/// exemption still requires the holder's Falcon signature (and the attestor's, on the dual path);
/// only the second, hash-family factor is dropped. And it can only ever RELAX — it is consulted
/// solely where `_slhStrictNow()`/`ringV3SlhStrict()` already said "strict", so it can never turn a
/// relaxed chain into a strict one, and can never freeze a wallet.
library LibSlhEconomics {

    /// The marginal on-chain cost of REQUIRING the hash-family factor: the ~1.15M-gas SLH-DSA
    /// verification (SlhDsaVerifierV2, measured 1,185,265 on the FIPS vectors and 1,195,839 live on
    /// Amoy) plus the calldata for its 7856-byte signature (~126k at 16 gas/byte).
    uint256 internal constant SLH_MARGINAL_GAS = 1_300_000;

    /// The threshold, in basis points of the transfer's value. 100 bps = 1%.
    uint256 internal constant SLH_ECONOMIC_BPS = 100;

    /// Default rolling window when governance has not set one.
    uint256 internal constant DEFAULT_WINDOW = 1 days;

    /// The oracle-independent share of TOTAL SUPPLY one account may move without the hash-family
    /// factor per window, when governance has not set an explicit ceiling: one thousandth, i.e.
    /// 0.1%. This is a CIRCUIT BREAKER against oracle manipulation, not the normal operating limit
    /// — under an honest oracle the break-even term of `effectiveCeiling` is the smaller of the two
    /// and is what actually binds. Sized to be generous enough not to interfere with ordinary small
    /// transfers at any plausible LEMNI price, and tight enough that a total price break still
    /// bounds one account to 0.1% of supply per day.
    uint256 internal constant DEFAULT_SUPPLY_DIVISOR = 1_000;

    /// Sanity bound on the basefee we are willing to price with (1e18 wei = 1e9 gwei — many orders
    /// of magnitude above anything a real chain produces). Above it the exemption is simply refused,
    /// which both fails closed and makes the break-even arithmetic below unable to overflow. An
    /// overflow here would revert the transfer, i.e. freeze the wallet, so it is ruled out by
    /// construction rather than left to chance.
    uint256 internal constant MAX_PRICEABLE_BASEFEE = 1e18;

    /// @notice The transfer's value expressed in native wei, derived ONLY from public views on the
    ///         ALREADY-DEPLOYED PriceOracle — so this change needs no oracle redeployment.
    ///
    ///         PriceOracle computes, internally:
    ///             valueUsd8 = amount * lemniUsd / 1e18
    ///             feeUsd8   = valueUsd8 * feeBps / 10_000
    ///             feeWei    = feeUsd8 * 1e18 / nativeUsd
    ///         Neither `lemniUsd` nor `nativeUsd` is exposed, but the two public views
    ///         `getMinFeeInWei` and `getFeeBps` are, and dividing the fee back out by its own rate
    ///         recovers the value in the same wei units:
    ///             valueWei = feeWei * 10_000 / feeBps
    ///
    /// @return 0 whenever the value cannot be established — which callers MUST treat as "no
    ///         exemption" (fail closed). Both oracle calls are wrapped so a reverting or
    ///         self-destructed oracle can never revert a transfer through this path.
    function transferValueWei(AppStorage storage s, uint256 amount) internal view returns (uint256) {
        address oracle = s.priceOracle;
        if (oracle == address(0)) return 0;

        uint16 bps;
        try PriceOracle(oracle).getFeeBps(amount) returns (uint16 b) {
            bps = b;
        } catch {
            return 0;
        }
        if (bps == 0) return 0;

        uint256 feeWei;
        try PriceOracle(oracle).getMinFeeInWei(amount) returns (uint256 f) {
            feeWei = f;
        } catch {
            return 0;
        }
        if (feeWei == 0) return 0;

        return (feeWei * 10_000) / uint256(bps);
    }

    /// @notice LEMNI wei this account has already moved WITHOUT an on-chain SLH verification inside
    ///         the current rolling window. Returns 0 once the window has rolled.
    function slhFreeUsed(AppStorage storage s, address account) internal view returns (uint256) {
        uint256 w = s.slhExemptWindow == 0 ? DEFAULT_WINDOW : s.slhExemptWindow;
        if (block.timestamp >= s.slhExemptWindowStart[account] + w) return 0;
        return s.slhExemptUsed[account];
    }

    /// @notice Charge `amount` against the account's rolling SLH-free budget, rolling the window
    ///         first if it has expired. Called on EVERY transfer/approve that completes without an
    ///         on-chain SLH verification — not only the exempt ones — so the budget reflects all
    ///         value that actually moved unprotected by the hash family.
    function noteSlhFree(AppStorage storage s, address account, uint256 amount) internal {
        uint256 w = s.slhExemptWindow == 0 ? DEFAULT_WINDOW : s.slhExemptWindow;
        if (block.timestamp >= s.slhExemptWindowStart[account] + w) {
            s.slhExemptWindowStart[account] = block.timestamp;
            s.slhExemptUsed[account] = amount;
        } else {
            s.slhExemptUsed[account] += amount;
        }
    }

    /// @notice True iff requiring on-chain SLH for this transfer would cost more than
    ///         SLH_ECONOMIC_BPS of the value being moved, AND every anti-gaming lock permits it.
    ///         Callers consult this ONLY where the strictness rule already said "strict"; it can
    ///         therefore only ever relax, never tighten.
    function economicallyExempt(AppStorage storage s, address account, uint256 amount)
        internal view returns (bool)
    {
        return economicallyExemptForGasAt(s, account, amount, SLH_MARGINAL_GAS, block.basefee);
    }

    /// @notice As `economicallyExempt`, but for a caller whose SLH cost is not one verification.
    ///         A Multi-Sig ring requires one SLH verification PER SIGNING MEMBER, so an M-of-N ring
    ///         passes `M * SLH_MARGINAL_GAS` and its break-even sits M times higher — the 1% rule is
    ///         measured against what THAT account is actually being asked to pay.
    function economicallyExemptForGas(
        AppStorage storage s,
        address account,
        uint256 amount,
        uint256 marginalGas
    ) internal view returns (bool) {
        return economicallyExemptForGasAt(s, account, amount, marginalGas, block.basefee);
    }

    /// @notice The same decision with the basefee supplied explicitly.
    ///
    ///         ON CHAIN this is always called with `block.basefee` — the consensus value, which is
    ///         the whole point of Lock 1. The explicit form exists for CLIENTS: most nodes execute
    ///         `eth_call` with a base fee of ZERO (so that gas-price checks never fail a simulated
    ///         call), which means an off-chain simulation of the no-argument form would read
    ///         basefee 0, fail closed, and always report "SLH required". A client that wants the
    ///         real answer reads `baseFeePerGas` from the pending block header and passes it here.
    ///         Being wrong is safe in both directions: a client that over-reports simply signs an
    ///         SLH signature that is then verified, and one that under-reports gets a clean revert.
    function economicallyExemptForGasAt(
        AppStorage storage s,
        address account,
        uint256 amount,
        uint256 marginalGas,
        uint256 basefee
    ) internal view returns (bool) {
        // Governance kill switch: restores the pre-1%-rule behaviour. Off by default.
        if (s.slhExemptDisabled) return false;

        // Lock 1: the cost is priced from the CHAIN's basefee, never the sender's gas price.
        if (basefee == 0 || basefee > MAX_PRICEABLE_BASEFEE) return false; // fail closed (Lock 4)

        // Lock 4: any oracle failure yields 0 here and denies the exemption.
        uint256 valueWei = transferValueWei(s, amount);
        if (valueWei == 0) return false;

        // THE RULE. Exempt only when the cost STRICTLY exceeds 1% of the value, i.e. the value is
        // below the break-even. Written as one multiplication on the (bounded) cost side so a very
        // large `valueWei` can never overflow and revert the transfer.
        uint256 costWei = marginalGas * basefee;
        uint256 breakevenWei = costWei * (10_000 / SLH_ECONOMIC_BPS);
        if (valueWei >= breakevenWei) return false;

        // Lock 2: the oracle-independent ceiling.
        uint256 ceiling = effectiveCeiling(s, amount, valueWei, breakevenWei);
        if (ceiling == 0 || amount > ceiling) return false;

        // Lock 3: splitting a large drain into sub-threshold pieces gains nothing — the ceiling
        // bounds the account's TOTAL SLH-free value per window, not just one transfer.
        return slhFreeUsed(s, account) + amount <= ceiling;
    }

    /// @notice The ceiling, in LEMNI wei, on both a single exempt transfer and the account's rolling
    ///         SLH-free total for this window.
    ///
    ///         An explicit `slhExemptMaxAmount` set by governance wins outright. Otherwise it is
    ///         computed, so that the rule can be ON by default without anyone having to guess a
    ///         number for the chain:
    ///
    ///           breakevenAmount = amount * breakevenWei / valueWei
    ///               The LEMNI amount whose value equals the break-even. The oracle's value function
    ///               is linear in `amount`, so one division inverts it from the reads already done.
    ///               This is precisely what the 1% rule already declared not worth protecting, so
    ///               under an honest oracle it never blocks a legitimate small transfer — and since
    ///               we only get here with valueWei < breakevenWei, it is always > amount, meaning a
    ///               single transfer is never refused by this term. What it does bound is the
    ///               ROLLING total: an account can move one break-even's worth per window without
    ///               the hash family, and no more.
    ///
    ///           supplyCap = totalSupply / DEFAULT_SUPPLY_DIVISOR
    ///               A pure on-chain quantity, with no oracle input at all. This is the term that
    ///               catches a manipulated spot price: crushing the LEMNI price inflates
    ///               breakevenAmount without limit, and this clamps it.
    ///
    ///         The smaller of the two governs, so BOTH must permit the exemption.
    function effectiveCeiling(
        AppStorage storage s,
        uint256 amount,
        uint256 valueWei,
        uint256 breakevenWei
    ) internal view returns (uint256) {
        uint256 explicitCeiling = s.slhExemptMaxAmount;
        if (explicitCeiling != 0) return explicitCeiling;

        uint256 supplyCap = s.totalSupply / DEFAULT_SUPPLY_DIVISOR;
        if (valueWei == 0) return 0; // caller already guards this; belt and braces

        // amount * breakevenWei cannot overflow in practice: `amount` is bounded by total supply
        // and breakevenWei by MAX_PRICEABLE_BASEFEE, but clamp defensively rather than risk a
        // revert (which would freeze the transfer) on a pathological chain.
        if (breakevenWei != 0 && amount > type(uint256).max / breakevenWei) return supplyCap;
        uint256 breakevenAmount = (amount * breakevenWei) / valueWei;

        return breakevenAmount < supplyCap ? breakevenAmount : supplyCap;
    }

    /// @notice The ceiling currently in force for `amount`, for clients and for the status view.
    ///         Returns 0 when the exemption cannot apply at all (disabled, unpriceable, or above
    ///         break-even).
    function currentCeiling(AppStorage storage s, uint256 amount, uint256 marginalGas, uint256 basefee)
        internal view returns (uint256)
    {
        if (s.slhExemptDisabled) return 0;
        if (basefee == 0 || basefee > MAX_PRICEABLE_BASEFEE) return 0;
        uint256 valueWei = transferValueWei(s, amount);
        if (valueWei == 0) return 0;
        uint256 breakevenWei = (marginalGas * basefee) * (10_000 / SLH_ECONOMIC_BPS);
        if (valueWei >= breakevenWei) return 0;
        return effectiveCeiling(s, amount, valueWei, breakevenWei);
    }

    // =====================================================================================
    // THE STRICTNESS RULE, AND THE VERIFICATION ITSELF
    //
    // Defined here rather than in any one facet so that transfers, approvals, recovery, CEX
    // sessions and burns are all governed by exactly the same code. Two facets each carrying their
    // own copy of this logic is how a security rule quietly drifts apart.
    //
    // HISTORY: through the reference verifier era (~24.6M gas per verify) strictness also depended
    // on `block.gaslimit >= 29M` — a chain whose blocks could not fit the verify auto-relaxed to
    // the Falcon floor so funds were never frozen. The optimized verifier (~1.2M) fits comfortably
    // inside any real chain's blocks, so THE GAS GATE IS RETIRED: strictness now depends only on a
    // verifier being wired and the owner not having force-relaxed. The owner's setLaipV3RelaxSlh
    // override remains the one escape hatch should a verifier defect ever surface.
    // =====================================================================================

    /// Protocol constant: SHA3-256(encodePoint(LOS P0)) — the lemniscate provenance anchor in mu.
    bytes32 internal constant LOS_COMMITMENT =
        0x5011820df0d8c8de5cee136edec7512fdb2ae279a33e7b25a52192e7931e04bb;

    /// Gas reserved for the tail (fee, token movement, events) after a best-effort SLH attempt.
    uint256 internal constant SLH_GAS_RESERVE = 1_500_000;
    /// Don't attempt the sub-call unless it could plausibly complete (avoids guaranteed-OOG waste).
    uint256 internal constant SLH_MIN_ATTEMPT = 1_300_000;

    /// @notice mu_trustless = keccak256(m || curveHash || nonce(32B) || LOS_COMMITMENT). keccak256
    ///         so the client and the chain agree byte-for-byte.
    function muTrustless(bytes32 m, bytes32 curveHash, uint256 nonce) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(m, curveHash, bytes32(nonce), LOS_COMMITMENT));
    }

    /// @notice Whether the hash-family factor is required at all on this chain. False only when no
    ///         verifier is wired (FREEZE GUARD: requiring a check we have no verifier for would
    ///         strand every wallet) or under the owner's emergency override. The old block-gas-limit
    ///         condition is retired — the optimized verifier fits any real chain's blocks.
    function chainStrict(AppStorage storage s) internal view returns (bool) {
        if (s.slhDsaVerifier == address(0)) return false;
        return !s.laipV3RelaxSlh;
    }

    /// @notice THE NO-DOWNGRADE GATE. Call this at the top of every LEGACY (pre-V3, Falcon-only)
    ///         value-moving entrypoint, so a wallet that has registered V3 keys cannot quietly
    ///         transact at the old strength.
    ///
    /// WHY THIS HAS TO EXIST. Registering V3 keys is meant to ADD the hash-family (SLH-DSA) factor,
    /// which is the ONLY factor in the system that does not rest on lattice hardness — Falcon
    /// (NTRU) and ML-DSA (Module-LWE) fall together if lattices fall. Without this gate the older
    /// Falcon-only entrypoints stay callable, so the hash factor is merely OPTIONAL: any client
    /// (or anyone calling the contract directly) can pick the cheaper legacy route and drop it.
    /// That silently costs the wallet the one property V3 was added to provide.
    ///
    /// WHY IT CANNOT FREEZE A WALLET — the safety argument, stated as an invariant:
    ///
    ///     this gate closes legacy  <=>  chainStrict(s) is true
    ///
    /// and `chainStrict` is true exactly when a verifier is wired AND the owner has not
    /// force-relaxed — i.e. exactly when the V3 path is able to run. So:
    ///
    ///   • No verifier wired          -> chainStrict false -> legacy stays OPEN.
    ///   • Owner's emergency relax    -> chainStrict false -> legacy REOPENS for everyone, which is
    ///                                   what makes setLaipV3RelaxSlh a real escape hatch and not a
    ///                                   half-measure that leaves migrated wallets stranded.
    ///   • Chain strict               -> the V3 entrypoint verifies through a live verifier, so
    ///                                   there is always somewhere to go.
    ///
    /// The 1% economic exemption does NOT enter here on purpose: an exempt transfer still goes
    /// through the V3 entrypoint (which drops to best-effort internally). The exemption decides how
    /// the V3 path behaves, never whether the legacy path is open.
    ///
    /// @param account The account whose funds/allowance the operation moves — NOT necessarily
    ///        msg.sender (on recovery it is the compromised wallet).
    function requireNotV3Downgrade(AppStorage storage s, address account) internal view {
        if (!s.laipV3[account].registered) return; // never migrated: legacy IS its normal path
        if (!chainStrict(s)) return;               // chain cannot enforce V3: never strand anyone
        revert LaipV3LegacyPathClosed(account);
    }

    /// @notice Two-party form for RECOVERY, where the V3 path needs BOTH wallets registered.
    ///
    /// @dev LAIPV3CapabilitiesFacet.recoveryTransferV3 calls _requireSameSeed(from, rescuer), which
    ///      reverts V3CapNotRegistered(rescuer) unless the RESCUER is registered too. So closing the
    ///      legacy recovery purely on `from` would strand a genuine rescue whenever the compromised
    ///      wallet had migrated but the rescuing one had not — and recovery is the emergency path,
    ///      the very last place to introduce a dead end. Close it only when the V3 recovery is
    ///      actually usable: both sides registered.
    function requireNotV3DowngradePair(AppStorage storage s, address from, address rescuer)
        internal view
    {
        if (!s.laipV3[from].registered || !s.laipV3[rescuer].registered) return;
        if (!chainStrict(s)) return;
        revert LaipV3LegacyPathClosed(from);
    }

    /// @notice The complete rule for a value-carrying operation: strict on this chain AND
    ///         requiring the verify must not cost more than 1% of the value being moved.
    function slhRequired(AppStorage storage s, address account, uint256 amount)
        internal view returns (bool)
    {
        if (!chainStrict(s)) return false;
        return !economicallyExempt(s, account, amount);
    }

    /// @dev STRICT: the hash-family factor is REQUIRED. Reverts unless a valid SLH signature
    ///      verifies on chain. A starved/out-of-gas verify reverts the WHOLE transaction (the
    ///      direct call propagates the OOG), so an attacker cannot skip SLH by under-funding gas.
    function strictSlh(
        AppStorage storage s,
        LaipV3Keys storage k,
        bytes32 m,
        uint256 nonce,
        bytes calldata slhPubKey,
        bytes calldata slhSig
    ) internal view returns (bool) {
        address verifier = s.slhDsaVerifier;
        require(verifier != address(0), "SLH verifier unset");
        require(slhSig.length != 0 && slhPubKey.length != 0, "SLH required"); // cannot be omitted
        if (keccak256(slhPubKey) != k.slhdsaPkHash) revert LaipV3SlhKeyMismatch();

        bytes memory mu = abi.encodePacked(muTrustless(m, k.curveHash, nonce));
        // Direct call, no gas cap: a false result OR an out-of-gas both fail the operation.
        if (!SlhDsaVerifier(verifier).verify(slhPubKey, mu, slhSig)) revert SlhDsaVerificationFailed();
        return true;
    }

    /// @dev RELAXED / best-effort. Returns true iff the factor was actually verified.
    ///      no verifier / empty sig -> false. Key mismatch or a completed FALSE result -> revert
    ///      (a real forgery is never disregarded). Not enough gas, or an out-of-gas inside the
    ///      verifier -> false, so funds are never frozen on a chain that cannot fit the verify.
    function bestEffortSlh(
        AppStorage storage s,
        LaipV3Keys storage k,
        bytes32 m,
        uint256 nonce,
        bytes calldata slhPubKey,
        bytes calldata slhSig
    ) internal view returns (bool) {
        address verifier = s.slhDsaVerifier;
        if (verifier == address(0)) return false;
        if (slhSig.length == 0 || slhPubKey.length == 0) return false; // caller opted out
        if (keccak256(slhPubKey) != k.slhdsaPkHash) revert LaipV3SlhKeyMismatch();

        if (gasleft() <= SLH_GAS_RESERVE + SLH_MIN_ATTEMPT) return false; // won't fit; disregarded
        uint256 cap = gasleft() - SLH_GAS_RESERVE;

        bytes memory mu = abi.encodePacked(muTrustless(m, k.curveHash, nonce));
        try SlhDsaVerifier(verifier).verify{gas: cap}(slhPubKey, mu, slhSig) returns (bool ok) {
            if (!ok) revert SlhDsaVerificationFailed(); // ran to completion: a false result is a forgery
            return true;
        } catch {
            return false; // out of gas or internal revert -> proceed on the Falcon floor
        }
    }
}

